import { parseDate } from "./utils"
import { eventsOn } from "./span"
import { shortMonth, weekStart } from "./month-strip"
import type { CalendarEvent } from "./types"

/**
 * The Agenda view is three months as a list of days. A day with nothing on it
 * is not listed at all, and the window rolls a month at a time.
 */

export const AGENDA_MONTHS = 3

export interface AgendaRow {
  date: Date
  key: string
  events: CalendarEvent[]
  isToday: boolean
  isPast: boolean
}

/** The three months the view is anchored on, from the 1st to the last day. */
export function agendaMonths(anchor: Date): { start: Date; end: Date } {
  const year = anchor.getFullYear()
  const month = anchor.getMonth()
  return {
    start: new Date(year, month, 1),
    end: new Date(year, month + AGENDA_MONTHS, 0),
  }
}

/** The span the view lists, padded out to whole weeks at both ends. */
export function agendaRange(anchor: Date): { start: Date; end: Date } {
  const { start, end } = agendaMonths(anchor)
  return { start: weekStart(start), end: addDays(weekStart(end), 6) }
}

/** The rows the list draws — one per day that has something on it. */
export function agendaRows(
  events: CalendarEvent[],
  anchor: Date,
  today: Date = new Date()
): AgendaRow[] {
  const { start, end } = agendaRange(anchor)
  const todayKey = parseDate(today)
  const rows: AgendaRow[] = []

  for (
    let date = start;
    date <= end;
    date = new Date(date.getFullYear(), date.getMonth(), date.getDate() + 1)
  ) {
    const onThisDay = eventsOn(events, date)
    if (!onThisDay.length) continue
    const key = parseDate(date)
    rows.push({
      date,
      key,
      events: onThisDay,
      isToday: key === todayKey,
      isPast: key < todayKey,
    })
  }

  return rows
}

export interface AgendaWeek {
  key: string
  start: Date
  end: Date
  isCurrent: boolean
  isNext: boolean
  isPrevious: boolean
  isPast: boolean
  days: AgendaRow[]
}

function addDays(date: Date, days: number): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days)
}

/** The list as the view draws it: the weeks that have anything in them. */
export function agendaWeeks(
  events: CalendarEvent[],
  anchor: Date,
  today: Date = new Date()
): AgendaWeek[] {
  const rows = agendaRows(events, anchor, today)
  const currentWeek = parseDate(weekStart(today))
  const nextWeek = parseDate(addDays(weekStart(today), 7))
  const lastWeek = parseDate(addDays(weekStart(today), -7))
  const weeks: AgendaWeek[] = []

  for (const row of rows) {
    const start = weekStart(row.date)
    const key = parseDate(start)
    let week = weeks[weeks.length - 1]

    if (week?.key !== key) {
      const end = addDays(start, 6)
      week = {
        key,
        start,
        end,
        isCurrent: key === currentWeek,
        isNext: key === nextWeek,
        isPrevious: key === lastWeek,
        isPast: parseDate(end) < parseDate(today),
        days: [],
      }
      weeks.push(week)
    }

    week.days.push(row)
  }

  return weeks
}

/** "Sep 6 – 12", or "Sep 27 – Oct 3" where the range crosses a month end. */
export function agendaRangeLabel(start: Date, end: Date): string {
  const from = `${shortMonth(start)} ${start.getDate()}`
  const to =
    start.getMonth() === end.getMonth()
      ? `${end.getDate()}`
      : `${shortMonth(end)} ${end.getDate()}`
  return `${from} – ${to}`
}

"use client"

import * as React from "react"

import type { EventActions, EventConfig, EventSlots, EventView } from "./types"

export interface EventContextValue {
  config: EventConfig
  actions: EventActions
  activeView: EventView
  slots: EventSlots
}

export const EventContext = React.createContext<EventContextValue | null>(null)

export function useEventContext(component: string): EventContextValue {
  const context = React.useContext(EventContext)
  if (!context) {
    throw new Error(`${component} must be rendered inside <Event>.`)
  }
  return context
}

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { useEventContext } from "./context"
import { calculateDiff, colorMap, handleSeconds } from "./utils"
import type { CalendarEvent } from "./types"

const COLORS = Object.keys(colorMap)

/**
 * The default edit and create modal: the calendar's own, shown where a host
 * has not replaced cell clicks and double clicks with its own panel.
 */
export function NewEventModal({
  open,
  onOpenChange,
  event,
}: {
  open: boolean
  onOpenChange: (open: boolean) => void
  event?: CalendarEvent
}) {
  const { actions } = useEventContext("NewEventModal")
  const editing = !!event && Object.prototype.hasOwnProperty.call(event, "id")

  const [form, setForm] = React.useState<CalendarEvent>({})
  const [errorMessage, setErrorMessage] = React.useState("")

  React.useEffect(() => {
    if (!open) return
    setForm({
      title: event?.title || "",
      date: event?.date || "",
      participant: event?.participant || "",
      fromDate: event?.fromDate || "",
      toDate: event?.toDate || "",
      fromTime: (event?.fromTime || "").slice(0, 5),
      toTime: (event?.toTime || "").slice(0, 5),
      venue: event?.venue || "",
      color: event?.color || "green",
      isFullDay: event?.isFullDay || false,
    })
    setErrorMessage("")
  }, [open, event])

  const set = (patch: Partial<CalendarEvent>) =>
    setForm((f) => ({ ...f, ...patch }))

  function validate(next: CalendarEvent): string {
    if (!next.date) return "Date is required"
    if (!next.fromTime && !next.isFullDay) return "Start Time is required"
    if (!next.toTime && !next.isFullDay) return "End Time is required"
    if (
      !next.isFullDay &&
      next.fromTime &&
      next.toTime &&
      calculateDiff(next.fromTime, next.toTime) <= 0
    ) {
      return "Start time must be less than End Time"
    }
    return ""
  }

  function submit() {
    const next: CalendarEvent = {
      ...form,
      fromDate: form.date,
      toDate: form.toDate || form.date,
    }
    const error = validate(next)
    setErrorMessage(error)
    if (error) return

    if (next.isFullDay) {
      next.fromTime = ""
      next.toTime = ""
    } else {
      next.fromTime = handleSeconds(next.fromTime || "")
      next.toTime = handleSeconds(next.toTime || "")
    }

    if (editing) {
      next.id = event!.id
      actions.updateEventState(next)
    } else {
      next.id = "#" + Math.random().toString(36).substring(3, 9)
      actions.createNewEvent(next)
    }
    onOpenChange(false)
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>{editing ? "Edit Event" : "New Event"}</DialogTitle>
        </DialogHeader>
        <div className="grid grid-cols-1 gap-4">
          <div className="flex flex-col gap-2">
            <Label htmlFor="ec-title">Title</Label>
            <Input
              id="ec-title"
              value={String(form.title ?? "")}
              placeholder="Meet with John Doe"
              onChange={(e) => set({ title: e.target.value })}
            />
          </div>
          <div className="flex flex-col gap-2">
            <Label htmlFor="ec-date">Date</Label>
            <Input
              id="ec-date"
              type="date"
              required
              value={String(form.date ?? "")}
              onChange={(e) => set({ date: e.target.value })}
            />
          </div>
          <div className="flex flex-col gap-2">
            <Label htmlFor="ec-person">Person</Label>
            <Input
              id="ec-person"
              value={String(form.participant ?? "")}
              placeholder="John Doe"
              onChange={(e) => set({ participant: e.target.value })}
            />
          </div>
          {!form.isFullDay && (
            <div className="flex flex-col gap-2">
              <Label htmlFor="ec-from">Start Time</Label>
              <Input
                id="ec-from"
                type="time"
                value={String(form.fromTime ?? "")}
                onChange={(e) => set({ fromTime: e.target.value })}
              />
            </div>
          )}
          {!form.isFullDay && (
            <div className="flex flex-col gap-2">
              <Label htmlFor="ec-to">End Time</Label>
              <Input
                id="ec-to"
                type="time"
                value={String(form.toTime ?? "")}
                onChange={(e) => set({ toTime: e.target.value })}
              />
            </div>
          )}
          <div className="flex flex-col gap-2">
            <Label htmlFor="ec-venue">Venue</Label>
            <Input
              id="ec-venue"
              value={String(form.venue ?? "")}
              placeholder="Frappe, Neelkanth Business Park"
              onChange={(e) => set({ venue: e.target.value })}
            />
          </div>
          <div className="flex flex-col gap-2">
            <Label>Color</Label>
            <Select
              value={String(form.color ?? "green")}
              onValueChange={(value) => set({ color: String(value) })}
            >
              <SelectTrigger className="w-full capitalize">
                <span
                  className="size-4 shrink-0 rounded-full shadow-md"
                  style={{
                    backgroundColor: colorMap[String(form.color || "green")]?.color,
                  }}
                />
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {COLORS.map((color) => (
                  <SelectItem key={color} value={color} className="capitalize">
                    {color}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <label className="flex items-center gap-2 text-sm">
            <Checkbox
              checked={!!form.isFullDay}
              onCheckedChange={(checked) => set({ isFullDay: !!checked })}
            />
            Full Day Event?
          </label>
          {errorMessage ? (
            <p className="text-sm text-destructive">{errorMessage}</p>
          ) : null}
        </div>
        <DialogFooter>
          <Button className="w-full" onClick={submit}>
            Submit
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import * as React from "react"
import {
  CalendarIcon,
  ClockIcon,
  MapPinIcon,
  PencilIcon,
  Trash2Icon,
  UserIcon,
  XIcon,
} from "lucide-react"

import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { useEventContext } from "./context"
import { parseDateEventPopupFormat } from "./utils"
import type { CalendarEvent, EventPopoverSlotProps } from "./types"

/** The card the default popover shows: the event, read. */
export function EventModalContent({
  calendarEvent,
  date,
  isEditMode,
  onClose,
  onEdit,
  onDelete,
}: {
  calendarEvent: CalendarEvent
  date: Date
  isEditMode?: boolean
  onClose: () => void
  onEdit: (e?: React.MouseEvent) => void
  onDelete: () => void
}) {
  return (
    <div className="w-80 p-4 text-[color:var(--ec-ink-gray-8)]">
      <div className="flex flex-row-reverse gap-2">
        <button
          type="button"
          aria-label="Close"
          className="cursor-pointer"
          onClick={(e) => {
            e.stopPropagation()
            onClose()
          }}
        >
          <XIcon className="size-4" />
        </button>
        {isEditMode && (
          <button
            type="button"
            aria-label="Edit"
            className="cursor-pointer"
            onClick={(e) => {
              e.stopPropagation()
              onEdit(e)
            }}
          >
            <PencilIcon className="size-4" />
          </button>
        )}
        {isEditMode && (
          <button
            type="button"
            aria-label="Delete"
            className="cursor-pointer"
            onClick={(e) => {
              e.stopPropagation()
              onDelete()
            }}
          >
            <Trash2Icon className="size-4" />
          </button>
        )}
      </div>
      <div className="flex flex-col gap-5">
        <div className="flex justify-between text-xl font-semibold">
          <span>{calendarEvent.title || "New Event"}</span>
        </div>
        <div className="flex flex-col gap-4">
          <div className="flex items-center gap-2">
            <CalendarIcon className="size-4" />
            <span className="text-[13px]">{parseDateEventPopupFormat(date)}</span>
          </div>
          {calendarEvent.participant ? (
            <div className="flex items-center gap-2">
              <UserIcon className="size-4" />
              <span className="text-[13px]">{calendarEvent.participant}</span>
            </div>
          ) : null}
          {calendarEvent.fromTime && calendarEvent.toTime ? (
            <div className="flex items-center gap-2">
              <ClockIcon className="size-4" />
              <span className="text-[13px]">
                {calendarEvent.fromTime} - {calendarEvent.toTime}
              </span>
            </div>
          ) : null}
          {calendarEvent.venue ? (
            <div className="flex items-center gap-2">
              <MapPinIcon className="size-4" />
              <span className="text-[13px]">{calendarEvent.venue}</span>
            </div>
          ) : null}
        </div>
      </div>
    </div>
  )
}

/**
 * The popover every drawn event opens — a grid pill, a month pill, an agenda
 * row. Controlled rather than trigger-driven: a single click opens it only
 * after a 200ms wait, so a double click can edit the event instead.
 */
export function EventPopover({
  open,
  onOpenChange,
  side,
  calendarEvent,
  date,
  onOpen,
  onClose,
  onEdit,
  onDelete,
  children,
}: {
  open: boolean
  onOpenChange: (open: boolean) => void
  side: "left" | "bottom" | "right" | "top"
  calendarEvent: CalendarEvent
  date: Date
  onOpen?: () => void
  onClose?: () => void
  onEdit: (e?: React.MouseEvent) => void
  onDelete: () => void
  children: React.ReactElement
}) {
  const context = useEventContext("EventPopover")
  const slot = context.slots.eventPopoverContent

  const wasOpen = React.useRef(false)
  React.useEffect(() => {
    if (open && !wasOpen.current) onOpen?.()
    if (!open && wasOpen.current) onClose?.()
    wasOpen.current = open
  }, [open, onOpen, onClose])

  const close = React.useCallback(() => onOpenChange(false), [onOpenChange])

  const slotProps: EventPopoverSlotProps = {
    calendarEvent,
    date,
    isEditMode: context.config.isEditMode,
    close,
  }

  return (
    <Popover
      open={open}
      onOpenChange={(value) => {
        // Honoured only on the way down — the click handler owns opening.
        if (!value) onOpenChange(false)
      }}
    >
      <PopoverTrigger
        render={children}
        // The pill's own click handler opens the popover after its wait;
        // Base UI's pointer-driven open would race it.
        onClick={(e: React.MouseEvent) => e.preventDefault()}
        nativeButton={false}
      />
      <PopoverContent side={side} align="center" className="w-auto p-0">
        {slot ? (
          slot(slotProps)
        ) : (
          <EventModalContent
            calendarEvent={calendarEvent}
            date={date}
            isEditMode={context.config.isEditMode}
            onClose={close}
            onEdit={(e) => {
              close()
              onEdit(e)
            }}
            onDelete={() => {
              close()
              onDelete()
            }}
          />
        )}
      </PopoverContent>
    </Popover>
  )
}

"use client"

import * as React from "react"
import { ChevronDownIcon, ChevronLeftIcon, ChevronRightIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { EventContext } from "./context"
import { EventStyles } from "./styles"
import { MonthYearCalendar } from "./month-year-calendar"
import { NewEventModal } from "./event-modal"
import { EventMonthly } from "./view-month"
import { EventWeekly } from "./view-week"
import { EventDaily } from "./view-day"
import { EventAgenda } from "./view-agenda"
import { popoverGate, setActiveEvent } from "./hooks"
import { agendaMonths, agendaRange } from "./agenda-days"
import { stripRange } from "./month-strip"
import { stripPlacement } from "./span"
import {
  formatMonthYear,
  getCalendarDates,
  getWeekMonthParts,
  handleSeconds,
  isTargetEditable,
  monthList,
  parseDate,
  calculateMinutes,
  convertMinutesToHours,
} from "./utils"
import type {
  CalendarEvent,
  EventCellClickData,
  EventConfig,
  EventHeaderSlotProps,
  EventPublicProps,
  EventSlots,
  EventView,
} from "./types"

const DEFAULT_CONFIG: EventConfig = {
  scrollToHour: 15,
  disableModes: [],
  defaultMode: "Month",
  isEditMode: false,
  eventIcons: {},
  hourHeight: 50,
  enableShortcuts: true,
  showIcon: true,
  timeFormat: "12h",
  weekends: ["sunday"],
} as EventConfig & { weekends: string[] }

const VIEW_SHORTCUTS: Record<string, EventView> = {
  m: "Month",
  w: "Week",
  a: "Agenda",
  d: "Day",
}

const OVERLAY_SELECTOR =
  '[role="dialog"], [role="alertdialog"], [role="menu"], [role="listbox"]'

interface NavState {
  year: number
  month: number
  dateIdx: number
  weekIdx: number
}

function datesOf(state: Pick<NavState, "year" | "month">) {
  return getCalendarDates(state.month, state.year)
}

function weeksOf(dates: Date[]): Date[][] {
  const copy = [...dates]
  const weeks: Date[][] = []
  while (copy.length) weeks.push(copy.splice(0, 7))
  return weeks
}

function indexOfDate(dates: Date[], date: Date | string) {
  return dates.findIndex(
    (d) => new Date(d).toDateString() === new Date(date).toDateString()
  )
}

function weekOfDate(weeks: Date[][], date?: Date) {
  if (!date) return 0
  const idx = weeks.findIndex((week) =>
    week.find((d) => d.toDateString() === new Date(date).toDateString())
  )
  return Math.max(idx, 0)
}

function firstOfMonth(dates: Date[], month: number, year: number) {
  return indexOfDate(dates, new Date(year, month, 1))
}

function lastOfMonth(dates: Date[], month: number, year: number) {
  return indexOfDate(dates, new Date(year, month + 1, 0))
}

function firstInMonth(weekDates: Date[], month: number) {
  return weekDates.find((d) => d.getMonth() === month) || weekDates[0]
}

export interface EventProps extends EventPublicProps, EventSlots {
  className?: string
  style?: React.CSSProperties
  /** Replaces the default header: the month label and every mover. */
  header?: (props: EventHeaderSlotProps) => React.ReactNode
  children?: React.ReactNode
}

/**
 * The calendar: a Month strip, a Week and a Day time grid, and an Agenda
 * list, with a view switcher and navigation over them — frappe-ui's
 * experimental Calendar, ported, with the espresso treatment baked in.
 */
export function Event({
  events: eventsProp = [],
  loading,
  config: configProp,
  onEventClick,
  onEventDblClick,
  onCellClick,
  onCreate,
  onUpdate,
  onDelete,
  onRangeChange,
  header,
  eventPopoverContent,
  eventDescription,
  eventSuffix,
  eventParticipant,
  agendaDayLabel,
  className,
  style,
}: EventProps) {
  const config = React.useMemo<EventConfig>(
    () => ({ ...DEFAULT_CONFIG, ...configProp }),
    [configProp]
  )

  const [activeView, setActiveView] = React.useState<EventView>(
    config.defaultMode
  )

  const today = React.useMemo(() => new Date(), [])
  const [nav, setNav] = React.useState<NavState>(() => {
    const year = today.getFullYear()
    const month = today.getMonth()
    const dates = getCalendarDates(month, year)
    const dateIdx = indexOfDate(dates, today)
    return {
      year,
      month,
      dateIdx,
      weekIdx: weekOfDate(weeksOf(dates), today),
    }
  })

  const dates = React.useMemo(() => datesOf(nav), [nav.month, nav.year]) // eslint-disable-line react-hooks/exhaustive-deps
  const weeks = React.useMemo(() => weeksOf(dates), [dates])
  const selectedDay: Date | undefined = dates[nav.dateIdx]

  /** Bumped by setCalendarDate; the Agenda scrolls back on every bump. */
  const [agendaJump, setAgendaJump] = React.useState(0)
  const [jumpDate, setJumpDate] = React.useState<Date>(today)

  const [selectedMonthDate, setSelectedMonthDate] = React.useState(() =>
    parseDate(new Date())
  )

  /* ── Events: a fresh internal copy the views edit ─────────────────────── */

  const parseEvents = React.useCallback((): CalendarEvent[] => {
    return (
      eventsProp?.map((event) => {
        const { fromDate, toDate, fromTime, toTime, ...rest } = event
        const timed = !!(fromTime && toTime)
        return {
          ...rest,
          date: fromDate,
          fromDateTime: fromDate + " " + fromTime,
          toDateTime: toDate + " " + toTime,
          fromDate,
          toDate,
          fromTime: timed ? handleSeconds(fromTime!) : fromTime,
          toTime: timed ? handleSeconds(toTime!) : toTime,
        }
      }) || []
    )
  }, [eventsProp])

  const [events, setEvents] = React.useState<CalendarEvent[]>(parseEvents)
  React.useEffect(() => {
    setEvents(parseEvents())
  }, [parseEvents])

  /* ── Navigation ───────────────────────────────────────────────────────── */

  const navRef = React.useRef(nav)
  navRef.current = nav

  const landMonth = React.useCallback(
    (
      year: number,
      month: number,
      land: "first" | "last"
    ): NavState => {
      const nextDates = getCalendarDates(month, year)
      const dateIdx =
        land === "first"
          ? firstOfMonth(nextDates, month, year)
          : lastOfMonth(nextDates, month, year)
      return {
        year,
        month,
        dateIdx,
        weekIdx: weekOfDate(weeksOf(nextDates), nextDates[dateIdx]),
      }
    },
    []
  )

  const incrementMonth = React.useCallback(
    (state: NavState): NavState => {
      let { month, year } = state
      month++
      if (month > 11) {
        month = 0
        year++
      }
      return landMonth(year, month, "first")
    },
    [landMonth]
  )

  const decrementMonth = React.useCallback(
    (state: NavState): NavState => {
      let { month, year } = state
      if (month === 0) {
        month = 11
        year--
      } else month--
      return landMonth(year, month, "last")
    },
    [landMonth]
  )

  const decrementMonthView = React.useCallback(
    (state: NavState): NavState => {
      const back = decrementMonth(state)
      return landMonth(back.year, back.month, "first")
    },
    [decrementMonth, landMonth]
  )

  const incrementWeek = React.useCallback(
    (state: NavState): NavState => {
      const stateDates = getCalendarDates(state.month, state.year)
      const stateWeeks = weeksOf(stateDates)
      const nextWeek = state.weekIdx + 1

      const landWeek = (s: NavState, weekIdx: number): NavState => {
        const d = getCalendarDates(s.month, s.year)
        const w = weeksOf(d)
        const day = firstInMonth(w[weekIdx], s.month)
        return { ...s, weekIdx, dateIdx: indexOfDate(d, day) }
      }

      if (nextWeek < stateWeeks.length) {
        const weekDates = stateWeeks[nextWeek]
        const spansNextMonth = weekDates.some((d) => d.getMonth() !== state.month)
        if (spansNextMonth) return landWeek(incrementMonth(state), 0)
        return landWeek(state, nextWeek)
      }
      return landWeek(incrementMonth(state), 0)
    },
    [incrementMonth]
  )

  const decrementWeek = React.useCallback(
    (state: NavState): NavState => {
      const stateDates = getCalendarDates(state.month, state.year)
      const stateWeeks = weeksOf(stateDates)
      const prevWeek = state.weekIdx - 1

      const landWeek = (s: NavState, weekIdx: number): NavState => {
        const d = getCalendarDates(s.month, s.year)
        const w = weeksOf(d)
        const day = firstInMonth(w[weekIdx], s.month)
        return { ...s, weekIdx, dateIdx: indexOfDate(d, day) }
      }

      if (prevWeek >= 0) {
        const weekDates = stateWeeks[prevWeek]
        const spansPrevMonth = weekDates.some((d) => d.getMonth() !== state.month)
        if (spansPrevMonth) {
          const back = decrementMonth(state)
          const backWeeks = weeksOf(getCalendarDates(back.month, back.year))
          return landWeek(back, backWeeks.length - 1)
        }
        return landWeek(state, prevWeek)
      }

      const back = decrementMonth(state)
      const backWeeks = weeksOf(getCalendarDates(back.month, back.year))
      let targetIndex = backWeeks.length - 1
      const hasNextMonthDates = backWeeks[targetIndex].some(
        (d) => d.getMonth() !== back.month
      )
      if (hasNextMonthDates && targetIndex > 0) targetIndex--
      return landWeek(back, targetIndex)
    },
    [decrementMonth]
  )

  const incrementDay = React.useCallback(
    (state: NavState): NavState => {
      const stateDates = getCalendarDates(state.month, state.year)
      const next = state.dateIdx + 1
      if (
        next > stateDates.length - 1 ||
        stateDates[next]?.getMonth() !== state.month
      ) {
        return incrementMonth(state)
      }
      const stateWeeks = weeksOf(stateDates)
      return {
        ...state,
        dateIdx: next,
        weekIdx: weekOfDate(stateWeeks, stateDates[next]),
      }
    },
    [incrementMonth]
  )

  const decrementDay = React.useCallback(
    (state: NavState): NavState => {
      const stateDates = getCalendarDates(state.month, state.year)
      const prev = state.dateIdx - 1
      if (prev < 0 || stateDates[prev]?.getMonth() !== state.month) {
        return decrementMonth(state)
      }
      const stateWeeks = weeksOf(stateDates)
      return {
        ...state,
        dateIdx: prev,
        weekIdx: weekOfDate(stateWeeks, stateDates[prev]),
      }
    },
    [decrementMonth]
  )

  const syncSelectedMonth = React.useCallback((state: NavState) => {
    setSelectedMonthDate((current) => {
      const currentDay = new Date(current + "T00:00").getDate()
      let tentative = new Date(state.year, state.month, currentDay)
      if (tentative.getMonth() !== state.month) {
        tentative = new Date(state.year, state.month + 1, 0)
      }
      return parseDate(tentative)
    })
  }, [])

  const activeViewRef = React.useRef(activeView)
  activeViewRef.current = activeView

  const increment = React.useCallback(() => {
    const view = activeViewRef.current
    setNav((state) => {
      const next =
        view === "Month" || view === "Agenda"
          ? incrementMonth(state)
          : view === "Week"
            ? incrementWeek(state)
            : incrementDay(state)
      syncSelectedMonth(next)
      return next
    })
  }, [incrementMonth, incrementWeek, incrementDay, syncSelectedMonth])

  const decrement = React.useCallback(() => {
    const view = activeViewRef.current
    setNav((state) => {
      const next =
        view === "Month" || view === "Agenda"
          ? decrementMonthView(state)
          : view === "Week"
            ? decrementWeek(state)
            : decrementDay(state)
      syncSelectedMonth(next)
      return next
    })
  }, [decrementMonthView, decrementWeek, decrementDay, syncSelectedMonth])

  const setCalendarDate = React.useCallback(
    (d?: Date | string) => {
      const dt = d ? new Date(d) : new Date()
      if (dt.toString() === "Invalid Date") return
      setAgendaJump((n) => n + 1)
      setJumpDate(dt)
      const year = dt.getFullYear()
      const month = dt.getMonth()
      const nextDates = getCalendarDates(month, year)
      let dateIdx = indexOfDate(nextDates, dt)
      if (dateIdx < 0) dateIdx = firstOfMonth(nextDates, month, year)
      const next = {
        year,
        month,
        dateIdx,
        weekIdx: weekOfDate(weeksOf(nextDates), dt),
      }
      setNav(next)
      syncSelectedMonth(next)
    },
    [syncSelectedMonth]
  )

  const updateActiveView = React.useCallback((value: EventView, d?: Date) => {
    setActiveView(value)
    setNav((state) => {
      const stateDates = getCalendarDates(state.month, state.year)
      if (value === "Day" && d) {
        const idx = indexOfDate(stateDates, d)
        if (idx >= 0) return { ...state, dateIdx: idx }
        return state
      }
      if (value === "Week") {
        return {
          ...state,
          weekIdx: weekOfDate(weeksOf(stateDates), stateDates[state.dateIdx]),
        }
      }
      return state
    })
  }, [])

  const onMonthYearChange = React.useCallback(
    (val: string | Date = "") => {
      const d = new Date(val)
      if (Number.isNaN(d.getTime())) return
      setSelectedMonthDate(parseDate(d))
      setCalendarDate(d)
    },
    [setCalendarDate]
  )

  /* ── Shortcuts ────────────────────────────────────────────────────────── */

  React.useEffect(() => {
    if (!config.enableShortcuts) return
    const handler = (e: KeyboardEvent) => {
      if (document.querySelector(OVERLAY_SELECTOR)) return
      if (isTargetEditable(e)) return
      const view = VIEW_SHORTCUTS[e.key.toLowerCase()]
      if (view) setActiveView(view)
      if (e.key.toLowerCase() === "t") setCalendarDate()
      if (e.key === "ArrowLeft") decrement()
      if (e.key === "ArrowRight") increment()
    }
    window.addEventListener("keydown", handler)
    return () => window.removeEventListener("keydown", handler)
  }, [config.enableShortcuts, setCalendarDate, decrement, increment])

  /* ── CRUD + cell clicks ───────────────────────────────────────────────── */

  const [showEventModal, setShowEventModal] = React.useState(false)
  const [newEvent, setNewEvent] = React.useState<CalendarEvent>({})

  const propsBag = React.useMemo<EventPublicProps>(
    () => ({
      events: eventsProp,
      loading,
      config: configProp,
      onEventClick,
      onEventDblClick,
      onCellClick,
    }),
    [eventsProp, loading, configProp, onEventClick, onEventDblClick, onCellClick]
  )

  const createNewEvent = React.useCallback(
    (event: CalendarEvent) => {
      event.fromDateTime = event.fromDate + " " + event.fromTime
      event.toDateTime = event.toDate + " " + event.toTime
      setEvents((list) => [...list, event])
      onCreate?.(event)
    },
    [onCreate]
  )

  const updateEventState = React.useCallback(
    (event: CalendarEvent) => {
      event = stripPlacement(event)
      event.fromDateTime = event.fromDate + " " + event.fromTime
      event.toDateTime = event.toDate + " " + event.toTime
      setEvents((list) => {
        const idx = list.findIndex((e) => e.id === event.id)
        if (idx < 0) return list
        const next = [...list]
        next[idx] = event
        return next
      })
      onUpdate?.(event)
    },
    [onUpdate]
  )

  const deleteEvent = React.useCallback(
    (eventID: CalendarEvent["id"]) => {
      setEvents((list) => list.filter((event) => event.id !== eventID))
      onDelete?.(eventID)
    },
    [onDelete]
  )

  const handleCellClick = React.useCallback(
    (
      e: React.MouseEvent | MouseEvent,
      date: Date | string,
      time = "",
      isFullDay = false
    ) => {
      if (popoverGate.open) {
        popoverGate.open = false
        return
      }
      setActiveEvent("")

      const data: EventCellClickData = {
        e,
        view: activeViewRef.current,
        date,
        time,
        isFullDay,
      }

      if (onCellClick) {
        onCellClick(data)
        return
      }

      // The default: the new-event modal, in edit mode.
      if (!config.isEditMode) return
      const formattedDate = parseDate(new Date(date))
      const base: CalendarEvent = {
        date: formattedDate,
        fromDate: formattedDate,
        toDate: formattedDate,
        isFullDay,
        participant: "",
        venue: "",
        title: "",
      }
      if (data.view === "Month" || data.view === "Agenda") {
        setNewEvent(base)
        setShowEventModal(true)
        return
      }
      const toTime = convertMinutesToHours(calculateMinutes(time) + 60).slice(
        0,
        -3
      )
      setNewEvent({ ...base, fromTime: time, toTime })
      setShowEventModal(true)
    },
    [onCellClick, config.isEditMode]
  )

  const actions = React.useMemo(
    () => ({
      createNewEvent,
      updateEventState,
      deleteEvent,
      handleCellClick,
      updateActiveView,
      setCalendarDate,
      props: propsBag,
    }),
    [
      createNewEvent,
      updateEventState,
      deleteEvent,
      handleCellClick,
      updateActiveView,
      setCalendarDate,
      propsBag,
    ]
  )

  /* ── Title + range ────────────────────────────────────────────────────── */

  const agendaAnchor = selectedDay ?? new Date()

  const currentMonthYear = (() => {
    if (activeView === "Day") {
      const dayDate = dates[nav.dateIdx]
      if (dayDate) {
        return `${daysShort[dayDate.getDay()]}, ${dayDate.getDate()} ${monthList[
          dayDate.getMonth()
        ].slice(0, 3)} ${dayDate.getFullYear()}`
      }
    }
    if (activeView === "Agenda") {
      const { start, end } = agendaMonths(agendaAnchor)
      const short = (d: Date) => monthList[d.getMonth()].slice(0, 3)
      return start.getFullYear() === end.getFullYear()
        ? `${short(start)} – ${short(end)} ${end.getFullYear()}`
        : `${short(start)} ${start.getFullYear()} – ${short(end)} ${end.getFullYear()}`
    }
    if (activeView !== "Week") return formatMonthYear(nav.month, nav.year)
    const weekDates = weeks[nav.weekIdx] || []
    if (!weekDates.length) return formatMonthYear(nav.month, nav.year)
    const parts = getWeekMonthParts(weekDates)
    if (parts.length === 1) return formatMonthYear(parts[0].month, parts[0].year)
    const short = monthList.map((m) => m.slice(0, 3))
    const first = parts[0]
    const last = parts[parts.length - 1]
    return first.year === last.year
      ? `${short[first.month]} - ${short[last.month]} ${first.year}`
      : `${short[first.month]} ${first.year} - ${short[last.month]} ${last.year}`
  })()

  const lastRangeKey = React.useRef("")
  React.useEffect(() => {
    if (!onRangeChange) return
    const range = (() => {
      if (activeView === "Day") {
        const day = selectedDay
        if (!day) return null
        const key = parseDate(day)
        return { startDate: key, endDate: key }
      }
      if (activeView === "Week") {
        const weekDates = weeks[nav.weekIdx] || []
        if (!weekDates.length) return null
        const ordered = [...weekDates].sort((a, b) => a.getTime() - b.getTime())
        return {
          startDate: parseDate(ordered[0]),
          endDate: parseDate(ordered[ordered.length - 1]),
        }
      }
      if (activeView === "Agenda") {
        const { start, end } = agendaRange(agendaAnchor)
        return { startDate: parseDate(start), endDate: parseDate(end) }
      }
      const r = stripRange(nav.month, nav.year)
      return { startDate: parseDate(r.start), endDate: parseDate(r.end) }
    })()
    if (!range) return
    const key = `${activeView}-${range.startDate}-${range.endDate}`
    if (key === lastRangeKey.current) return
    lastRangeKey.current = key
    onRangeChange({ view: activeView, ...range })
  })

  /* ── Render ───────────────────────────────────────────────────────────── */

  const enabledModes = (
    ["Day", "Week", "Month", "Agenda"] as EventView[]
  ).filter((mode) => !config.disableModes.includes(mode))

  const slots: EventSlots = React.useMemo(
    () => ({
      eventPopoverContent,
      eventDescription,
      eventSuffix,
      eventParticipant,
      agendaDayLabel,
    }),
    [
      eventPopoverContent,
      eventDescription,
      eventSuffix,
      eventParticipant,
      agendaDayLabel,
    ]
  )

  const headerProps: EventHeaderSlotProps = {
    currentMonthYear,
    currentYear: nav.year,
    currentMonth: nav.month,
    enabledModes: enabledModes.map((value) => ({ label: value, value })),
    activeView,
    decrement,
    increment,
    updateActiveView,
    setCalendarDate,
    onMonthYearChange,
    selectedMonthDate,
  }

  const contextValue = React.useMemo(
    () => ({ config, actions, activeView, slots }),
    [config, actions, activeView, slots]
  )

  return (
    <EventContext.Provider value={contextValue}>
      <EventStyles />
      <div className={cn("ec-scope flex h-full flex-col", className)} style={style}>
        {header ? (
          header(headerProps)
        ) : (
          <DefaultHeader {...headerProps} />
        )}

        {activeView === "Month" && (
          <EventMonthly
            events={events}
            currentMonth={nav.month}
            currentYear={nav.year}
            currentDate={selectedDay}
            jumpDate={jumpDate}
            config={config}
          />
        )}
        {activeView === "Week" && (
          <EventWeekly
            events={events}
            weeklyDates={weeks[nav.weekIdx] ?? []}
            config={config}
          />
        )}
        {activeView === "Day" && selectedDay && (
          <EventDaily events={events} currentDate={selectedDay} config={config} />
        )}
        {activeView === "Agenda" && (
          <EventAgenda
            events={events}
            anchor={agendaAnchor}
            jump={agendaJump}
            loading={loading}
            slots={slots}
          />
        )}

        <NewEventModal
          open={showEventModal}
          onOpenChange={setShowEventModal}
          event={newEvent}
        />
      </div>
    </EventContext.Provider>
  )
}

const daysShort = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"]

/** The default header: month picker, movers, Today and the view switcher. */
function DefaultHeader({
  currentMonthYear,
  enabledModes,
  activeView,
  decrement,
  increment,
  updateActiveView,
  setCalendarDate,
  onMonthYearChange,
  selectedMonthDate,
}: EventHeaderSlotProps) {
  const [open, setOpen] = React.useState(false)
  return (
    <div className="mb-2 flex justify-between">
      <div className="flex items-center">
        <Popover open={open} onOpenChange={setOpen}>
          <PopoverTrigger
            render={
              <Button variant="ghost" className="gap-2 text-lg font-medium">
                {currentMonthYear}
                <ChevronDownIcon className="size-4" />
              </Button>
            }
          />
          <PopoverContent align="start" className="w-auto p-2">
            <MonthYearCalendar
              mode="single"
              selected={new Date(selectedMonthDate + "T00:00")}
              defaultMonth={new Date(selectedMonthDate + "T00:00")}
              onSelect={(date) => {
                if (date) onMonthYearChange(date)
                setOpen(false)
              }}
            />
          </PopoverContent>
        </Popover>
      </div>
      <div className="flex items-center gap-x-1">
        <Button
          variant="ghost"
          size="icon"
          aria-label="Previous"
          onClick={decrement}
        >
          <ChevronLeftIcon />
        </Button>
        <Button variant="ghost" onClick={() => setCalendarDate()}>
          Today
        </Button>
        <Button variant="ghost" size="icon" aria-label="Next" onClick={increment}>
          <ChevronRightIcon />
        </Button>
        <Tabs
          value={activeView}
          onValueChange={(value) => updateActiveView(value as EventView)}
          className="ml-2"
        >
          <TabsList>
            {enabledModes.map((mode) => (
              <TabsTrigger key={mode.value} value={mode.value}>
                {mode.label}
              </TabsTrigger>
            ))}
          </TabsList>
        </Tabs>
      </div>
    </div>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { useEventContext } from "./context"
import { EventPopover } from "./event-popover"
import { NewEventModal } from "./event-modal"
import { useEventBase } from "./use-event-base"
import {
  EVENT_HEIGHT_THRESHOLD,
  calculateDiff,
  calculateMinutes,
  convertMinutesToHours,
  formattedDuration,
  paintedEventHeight,
} from "./utils"
import {
  COLUMN_RULE,
  PILL_INSET,
  PILL_MARGIN,
  isAllDayLike,
  shiftEventDays,
  shiftEventMinutes,
  weekLaneGap,
  weekLaneHeight,
  weekLanePitch,
} from "./span"
import type { CalendarEvent, EventRowBar } from "./types"

/** The ring's width, and the pill's corner radius it runs concentric with. */
const CUT = 2
const PILL_RADIUS = 8
const DAY_COLUMNS = 7

const clampMap: Record<number, string> = {
  1: "line-clamp-1",
  2: "line-clamp-2",
  3: "line-clamp-3",
  4: "line-clamp-4",
  5: "line-clamp-5",
  6: "line-clamp-6",
}
const clampClass = (lines: number) =>
  clampMap[Math.min(Math.max(1, Math.floor(lines)), 6)]

/**
 * A timed pill in the Week and Day grids, and the bars of their all-day rows.
 * An overnight event arrives once per day with `segFromTime`/`segToTime`
 * clipped to that day.
 */
export function EventGridPill({
  event,
  date,
  bar,
  narrow,
  inset,
  slotsKey,
}: {
  event: CalendarEvent
  date: Date
  /** Places the card as a bar across a row of day columns. */
  bar?: EventRowBar
  /** Drawn in a week whose columns are narrow. */
  narrow?: boolean
  /** How far inside its column the pill's own edge lands, in pixels. */
  inset?: number
  slotsKey?: string
}) {
  void slotsKey
  const context = useEventContext("EventGridPill")
  const {
    config,
    actions,
    bgStyle,
    isActive,
    preventClick,
    showEventModal,
    setShowEventModal,
    handleEventClick,
    handleEventEdit,
    handleEventDelete,
    registerDeleteShortcut,
    unregisterDeleteShortcut,
  } = useEventBase(event)

  const [isPopoverOpen, setPopoverOpen] = React.useState(false)
  const [isResizing, setResizing] = React.useState(false)
  const [isRepositioning, setRepositioning] = React.useState(false)
  // Pixel offset of the card while dragged, and the move it stands for.
  const [drag, setDrag] = React.useState({ xAxis: 0, yAxis: 0 })
  const dragState = React.useRef({ dayShift: 0, minuteShift: 0, updated: false })

  // The live times while a drag or resize previews the move.
  const [previewTimes, setPreviewTimes] = React.useState<{
    fromTime?: string
    toTime?: string
  } | null>(null)

  const eventRef = React.useRef<HTMLDivElement | null>(null)
  const contentRef = React.useRef<HTMLDivElement | null>(null)
  const titleRef = React.useRef<HTMLParagraphElement | null>(null)
  const timeRef = React.useRef<HTMLParagraphElement | null>(null)

  const minuteHeight = config.hourHeight / 60
  const height15Min = minuteHeight * 15

  const isAllDay = isAllDayLike(event)
  const popoverSide = context.activeView === "Week" ? "left" : "bottom"
  const EventIcon = event.type ? config.eventIcons[event.type] : undefined

  const placedFromTime = () =>
    String(event.segFromTime || event.fromTime || "00:00")
  // While the card is being stretched, the geometry follows the stretch: the
  // wrapper that holds the pill keeps step with the pointer, so the release
  // has nothing to jump between — the Vue original's live mutation, done
  // through the preview.
  const placedToTime = () =>
    String(
      (isResizing && previewTimes?.toTime) ||
        event.segToTime ||
        event.toTime ||
        "00:00"
    )

  const pillInset = inset ?? PILL_INSET
  const wrapperInset = pillInset - PILL_MARGIN

  /** Where a timed pill sits in its column — see the frappe source. */
  const timedBox = React.useCallback(
    function timedBox(
      startMinutes: number,
      minutes: number,
      hall?: number,
      over: CalendarEvent[] = []
    ): {
      top: number
      bottom: number
      height: number
      hallNumber: number
      left: (extra?: number) => string
      right: (extra?: number) => string
    } {
      const height = Math.round(paintedEventHeight(minutes, minuteHeight))
      let top = Math.round(
        Math.min(startMinutes * minuteHeight, 24 * config.hourHeight - height)
      )
      let bottom = top + height
      const beneath = over.map((other) =>
        timedBox(
          other.startTime || 0,
          (other.endTime || 0) - (other.startTime || 0),
          other.hallNumber,
          other.over || []
        )
      )
      for (let moved = true; moved; ) {
        moved = false
        for (const other of beneath) {
          if (other.top <= top && top < other.top + CUT) {
            top = other.top + CUT
            moved = true
          }
          if (other.bottom - CUT < bottom && bottom <= other.bottom) {
            bottom = other.bottom - CUT
            moved = true
          }
        }
      }
      const hallNumber = hall || 0
      return {
        top,
        bottom,
        height: bottom - top,
        hallNumber,
        left: (extra = 0) =>
          `calc(${hallNumber * 20}% + ${pillInset + extra}px)`,
        right: (extra = 0) => `calc(7% + ${hallNumber * 2 * CUT - extra}px)`,
      }
    },
    [minuteHeight, config.hourHeight, pillInset]
  )

  const ownBox = () =>
    timedBox(
      calculateMinutes(placedFromTime()),
      calculateDiff(placedFromTime(), placedToTime()),
      event.hallNumber,
      (event.over || []) as CalendarEvent[]
    )

  /** One cut per event this pill lies on. */
  const cuts = (() => {
    if (isAllDay || isResizing || isRepositioning) return []
    const over = (event.over || []) as CalendarEvent[]
    if (!over.length) return []
    const own = ownBox()
    const ring: React.CSSProperties = {
      top: `${own.top - CUT}px`,
      left: own.left(-CUT),
      right: own.right(CUT),
      height: `${own.height + 2 * CUT}px`,
      borderRadius: `${PILL_RADIUS + CUT}px`,
    }
    return over.map((other) => {
      const box = timedBox(
        other.startTime || 0,
        (other.endTime || 0) - (other.startTime || 0),
        other.hallNumber,
        other.over || []
      )
      const clip = `inset(${box.top}px ${box.right()} calc(100% - ${box.top + box.height}px) ${box.left()} round ${PILL_RADIUS}px)`
      return { id: `${other.id}-${other.hallNumber}-${other.idx}`, clip, ring }
    })
  })()

  const containerStyle: React.CSSProperties = (() => {
    if (bar) {
      const span = bar.endCol - bar.startCol + 1
      return {
        position: "absolute",
        left: `calc(${(bar.startCol / DAY_COLUMNS) * 100}% + ${wrapperInset}px)`,
        width: `calc(${(span / DAY_COLUMNS) * 100}% - ${pillInset * 2 + COLUMN_RULE}px)`,
        top: `${weekLaneGap(narrow) + bar.lane * weekLanePitch(narrow)}px`,
        height: `${weekLaneHeight(narrow)}px`,
        transform: `translate(${drag.xAxis}px, 0)`,
        zIndex: isRepositioning ? 100 : 1,
        transition: isRepositioning ? "none" : "all 0.1s ease",
      }
    }
    if (isAllDay) {
      return {
        transform: `translate(${drag.xAxis}px, ${drag.yAxis}px)`,
        zIndex: isRepositioning ? 100 : (event.idx || 0) + 1,
      }
    }
    const { top, height, hallNumber } = ownBox()
    const dragging = isResizing || isRepositioning
    const box = timedBox(0, 0, hallNumber)
    const left = dragging
      ? `${wrapperInset}px`
      : `calc(${hallNumber * 20}% + ${wrapperInset}px)`
    const right = dragging ? `${PILL_MARGIN}px` : box.right(-PILL_MARGIN)
    return {
      position: "absolute",
      top: `${top}px`,
      left,
      right,
      // The popover trigger merges a w-fit of its own onto this wrapper;
      // spelled inline, the width stays the stretch between the insets.
      width: "auto",
      height: `${height}px`,
      zIndex: dragging ? 100 : 0,
      transform: `translate(${drag.xAxis}px, ${drag.yAxis}px)`,
      transition: dragging ? "none" : "all 0.1s ease",
    }
  })()

  // A timed pill keeps 1px off the top and the bottom, so two events that
  // meet on an hour stay two blocks (the espresso treatment). Across, it
  // takes the whole of the width its wrapper stretches to.
  const timed = !isAllDay
  const innerStyle: React.CSSProperties = {
    ...bgStyle,
    height: timed && !isResizing ? "calc(100% - 2px)" : "100%",
    marginTop: timed ? 1 : undefined,
    marginBottom: timed ? 1 : undefined,
    width: "100%",
    maxWidth: "100%",
    cursor: isRepositioning ? "grabbing" : "pointer",
  }

  const isTight = !!narrow
  const timeLabel = formattedDuration(
    (previewTimes?.fromTime ?? event.fromTime ?? "") as string,
    (previewTimes?.toTime ?? event.toTime ?? "") as string,
    config.timeFormat
  )
  const isCompact =
    !isAllDay &&
    calculateDiff(placedFromTime(), placedToTime()) * minuteHeight <
      EVENT_HEIGHT_THRESHOLD

  /* ── Line clamps and floors, measured ─────────────────────────────────── */

  const [measure, setMeasure] = React.useState({
    contentWidth: 0,
    titleClamp: undefined as string | undefined,
    timeClamp: "line-clamp-1",
    showTitle: true,
    showTime: true,
  })

  const TITLE_FLOOR = isTight ? 20 : 24
  const TIME_FLOOR = 16
  const COMPACT_GAP = 6
  const iconWidth = config.showIcon && EventIcon ? 16 + 8 : 0

  const remeasure = React.useCallback(() => {
    const content = contentRef.current
    const pill = eventRef.current
    if (!content || !pill) return
    const contentWidth = content.clientWidth

    const lineHeightOf = (el: HTMLElement) =>
      parseFloat(getComputedStyle(el).lineHeight)
    const contentHeight = pill.clientHeight - 8 - 2

    let titleClamp: string | undefined
    let timeClamp = "line-clamp-1"
    let titleLines: number | undefined

    if (!isAllDay && titleRef.current && (event.fromTime || event.toTime)) {
      const timeLine = timeRef.current ? lineHeightOf(timeRef.current) : 0
      titleLines = Math.max(
        1,
        Math.floor((contentHeight - timeLine) / lineHeightOf(titleRef.current))
      )
      titleClamp = clampClass(titleLines)
      if (timeRef.current) {
        const titleLine = lineHeightOf(titleRef.current)
        const natural = Math.round(titleRef.current.scrollHeight / titleLine)
        const taken = Math.min(natural, titleLines) * titleLine
        timeClamp = clampClass(
          (contentHeight - taken) / lineHeightOf(timeRef.current)
        )
      }
    }

    let showTitle = true
    let showTime = true
    if (isCompact && contentWidth) {
      showTitle = contentWidth - iconWidth >= TITLE_FLOOR
      if (!showTitle) showTime = false
      else {
        const title = Math.min(
          titleRef.current?.scrollWidth ?? TITLE_FLOOR,
          TITLE_FLOOR
        )
        showTime =
          contentWidth - iconWidth - COMPACT_GAP - title >= TIME_FLOOR
      }
    }

    setMeasure((prev) => {
      const next = { contentWidth, titleClamp, timeClamp, showTitle, showTime }
      return prev.contentWidth === next.contentWidth &&
        prev.titleClamp === next.titleClamp &&
        prev.timeClamp === next.timeClamp &&
        prev.showTitle === next.showTitle &&
        prev.showTime === next.showTime
        ? prev
        : next
    })
  }, [isAllDay, isCompact, event.fromTime, event.toTime, iconWidth, TITLE_FLOOR])

  React.useLayoutEffect(() => {
    remeasure()
  })

  React.useEffect(() => {
    const content = contentRef.current
    if (!content || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(() => remeasure())
    observer.observe(content)
    return () => observer.disconnect()
  }, [remeasure])

  /* ── Resize ───────────────────────────────────────────────────────────── */

  function newEventEndTime(heightPx: number) {
    let end = heightPx / minuteHeight + calculateMinutes(placedFromTime())
    end = Math.floor(end)
    if (end > 1440) end = 1440
    return convertMinutesToHours(end)
  }

  function handleResizeMouseDown(e: React.MouseEvent) {
    e.stopPropagation()
    const pill = eventRef.current
    if (!pill) return
    setResizing(true)
    setRepositioning(false)

    const oldTime = event.toTime
    let latest = event.toTime

    const resize = (ev: MouseEvent) => {
      preventClick.current = true
      if (!eventRef.current) return
      const diff = ev.clientY - eventRef.current.getBoundingClientRect().top
      const height = Math.round(diff / height15Min) * height15Min
      eventRef.current.style.height = height + "px"
      eventRef.current.style.width = "100%"
      const toTime = newEventEndTime(height)
      latest = toTime
      setPreviewTimes({ fromTime: event.fromTime, toTime })
    }

    const stop = () => {
      setResizing(false)
      setPreviewTimes(null)
      if (eventRef.current) {
        // Put back what React rendered, not nothing: React's diff still
        // holds these values, so a blank would never be re-written and the
        // card would shrink to its content.
        eventRef.current.style.height = "calc(100% - 2px)"
        eventRef.current.style.width = "100%"
      }
      if (oldTime !== latest && latest) {
        const next: CalendarEvent = { ...event, toTime: latest }
        if (next.segToTime) next.segToTime = latest
        actions.updateEventState(next)
      }
      window.removeEventListener("mousemove", resize)
    }

    window.addEventListener("mousemove", resize)
    window.addEventListener("mouseup", stop, { once: true })
  }

  /* ── Reposition ───────────────────────────────────────────────────────── */

  function columnWidth(): number {
    const row = eventRef.current?.closest(
      "[data-day-columns]"
    ) as HTMLElement | null
    if (row) return row.clientWidth / DAY_COLUMNS
    return eventRef.current?.clientWidth || 1
  }

  function handleRepositionMouseDown(e: React.MouseEvent) {
    if (!config.isEditMode) return
    if (isResizing) return
    e.preventDefault()
    const prevY = e.clientY
    const pill = eventRef.current
    if (!pill) return
    const rect = pill.getBoundingClientRect()
    const activeView = context.activeView
    dragState.current = { dayShift: 0, minuteShift: 0, updated: false }

    const mousemove = (ev: MouseEvent) => {
      if (isPopoverOpen) setPopoverOpen(false)
      setRepositioning(true)
      preventClick.current = true
      if (!eventRef.current) return

      let xAxis = 0
      let yAxis = 0

      if (activeView === "Week") {
        const width = columnWidth()
        let diff = Math.floor((ev.clientX - rect.left) / width)
        const column = bar ? bar.startCol : new Date(date).getDay()
        diff = Math.max(-column, Math.min(diff, DAY_COLUMNS - 1 - column))
        xAxis = Math.ceil(diff * width)
        dragState.current.dayShift = diff
      }
      if (!isAllDay) {
        let diffY = ev.clientY - prevY
        const parentRect = eventRef.current
          .closest("[data-time-grid]")
          ?.getBoundingClientRect()
        if (parentRect) {
          if (ev.clientY < parentRect.top) diffY = parentRect.top - rect.top
          if (ev.clientY > parentRect.bottom)
            diffY = parentRect.bottom - rect.bottom
          diffY = Math.round(diffY / height15Min) * height15Min
          yAxis = diffY
          dragState.current.minuteShift = Math.round(diffY / minuteHeight)
        }
      }

      setDrag({ xAxis, yAxis })

      // The subtitle previews where the event would land.
      const preview = shiftEventMinutes(
        { ...event },
        dragState.current.minuteShift
      )
      setPreviewTimes({ fromTime: preview.fromTime, toTime: preview.toTime })
      dragState.current.updated =
        dragState.current.dayShift !== 0 || dragState.current.minuteShift !== 0
    }

    const mouseup = (ev: MouseEvent) => {
      ev.preventDefault()
      setRepositioning(false)
      setPreviewTimes(null)
      if (dragState.current.updated) {
        const next = { ...event }
        if (dragState.current.minuteShift)
          shiftEventMinutes(next, dragState.current.minuteShift)
        if (dragState.current.dayShift)
          shiftEventDays(next, dragState.current.dayShift)
        actions.updateEventState(next)
        dragState.current.updated = false
      }
      setDrag({ xAxis: 0, yAxis: 0 })
      dragState.current.dayShift = 0
      dragState.current.minuteShift = 0
      window.removeEventListener("mousemove", mousemove)
      window.removeEventListener("mouseup", mouseup)
    }

    window.addEventListener("mousemove", mousemove)
    window.addEventListener("mouseup", mouseup)
  }

  /* ── Render ───────────────────────────────────────────────────────────── */

  const padClass = isAllDay ? (isTight ? "px-1 py-0.5" : "p-1") : "p-1"

  return (
    <>
      {cuts.map((cut) => (
        <div
          key={cut.id}
          className="ec-cut pointer-events-none absolute inset-0"
          style={{ clipPath: cut.clip }}
        >
          <div
            className="absolute"
            style={{ ...cut.ring, backgroundColor: "var(--ec-surface-base)" }}
          />
        </div>
      ))}
      <EventPopover
        open={isPopoverOpen}
        onOpenChange={setPopoverOpen}
        side={popoverSide}
        calendarEvent={event}
        date={date}
        onOpen={registerDeleteShortcut}
        onClose={unregisterDeleteShortcut}
        onEdit={handleEventEdit}
        onDelete={handleEventDelete}
      >
        <div className="flex" style={containerStyle}>
          <div
            ref={eventRef}
            className={cn(
              "event mx-px shrink-0 overflow-hidden rounded-[8px] transition-all duration-75",
              bar && "h-full",
              isAllDay && !bar && "h-7",
              !isAllDay && "min-h-6",
              isActive && "active",
              bar && !bar.isStart && "rounded-l-none",
              bar && !bar.isEnd && "rounded-r-none",
              !isAllDay && event.segIsEnd === false && "rounded-b-none",
              !isAllDay && event.segIsStart === false && "rounded-t-none",
              !!event.isDraft && "event-draft"
            )}
            style={innerStyle}
            onClick={(e) => {
              e.stopPropagation()
              e.preventDefault()
              handleEventClick(e, () => setPopoverOpen((o) => !o), isPopoverOpen)
            }}
            onDoubleClick={(e) => {
              e.preventDefault()
              handleEventEdit(e)
            }}
            onMouseDown={handleRepositionMouseDown}
          >
            <div className={cn("ec-pad flex h-full gap-1.5", padClass)}>
              {event.fromTime && !isTight ? (
                <div
                  className={cn(
                    "event-border my-px w-[2px] shrink-0 rounded-[8px]",
                    event.isDraft && "invisible"
                  )}
                />
              ) : null}
              <div
                ref={contentRef}
                className={cn(
                  "ec-body relative flex h-full min-w-0 flex-1 gap-2 overflow-hidden select-none",
                  isAllDay ? "items-center" : "items-start"
                )}
              >
                {config.showIcon && EventIcon ? (
                  <div>
                    <EventIcon className="mt-px size-3.5" />
                  </div>
                ) : null}
                <div
                  className={cn(
                    "flex min-w-0 overflow-hidden",
                    isCompact ? "items-baseline gap-1.5" : "w-full flex-col gap-0.5"
                  )}
                >
                  {(!isCompact || measure.showTitle) && (
                    <p
                      ref={titleRef}
                      className={cn(
                        "event-title break-words",
                        isTight
                          ? "text-[12px] leading-4 font-medium"
                          : isCompact || isAllDay
                            ? "text-[13px] leading-5 font-medium"
                            : "text-[13px] leading-snug font-medium",
                        isCompact
                          ? cn(isTight ? "min-w-5" : "min-w-6", "shrink-[100] truncate")
                          : measure.titleClamp,
                        event.isDeclined &&
                          "text-[color:var(--ec-ink-gray-5)]! line-through"
                      )}
                    >
                      {event.title || "[No title]"}
                    </p>
                  )}
                  {!isAllDay && !isTight && (!isCompact || measure.showTime) ? (
                    <p
                      ref={timeRef}
                      className={cn(
                        "event-subtitle text-[12px]",
                        isCompact ? "min-w-4 truncate" : measure.timeClamp
                      )}
                    >
                      {timeLabel}
                    </p>
                  ) : null}
                </div>
              </div>
            </div>
            {config.isEditMode && !isAllDay && event.segIsEnd !== false ? (
              <div
                className="absolute -bottom-1 h-3 w-full cursor-ns-resize"
                onMouseDown={handleResizeMouseDown}
              />
            ) : null}
          </div>
        </div>
      </EventPopover>
      <NewEventModal
        open={showEventModal}
        onOpenChange={setShowEventModal}
        event={event}
      />
    </>
  )
}

"use client"

import * as React from "react"

import {
  calculateMinutes,
  findOverlappingEventsCount,
  twelveHoursFormat,
  twentyFourHoursFormat,
} from "./utils"
import { daySegments, isAllDayLike } from "./span"
import type {
  CalendarEvent,
  EventConfig,
  GroupedCalendarEvents,
} from "./types"

/* ── One clock for the whole calendar ──────────────────────────────────── */

let now = new Date()
let timer: ReturnType<typeof setInterval> | undefined
const nowListeners = new Set<() => void>()

const tick = () => {
  now = new Date()
  nowListeners.forEach((l) => l())
}
const tickIfVisible = () => {
  if (document.visibilityState === "visible") tick()
}

function subscribeNow(listener: () => void) {
  if (!nowListeners.size) {
    tick()
    // 30s keeps the minute-resolution marker within half a minute of the
    // truth without waking the page every second.
    timer = setInterval(tick, 30_000)
    document.addEventListener("visibilitychange", tickIfVisible)
    window.addEventListener("focus", tick)
  }
  nowListeners.add(listener)
  return () => {
    nowListeners.delete(listener)
    if (!nowListeners.size) {
      if (timer) clearInterval(timer)
      timer = undefined
      document.removeEventListener("visibilitychange", tickIfVisible)
      window.removeEventListener("focus", tick)
    }
  }
}

/** A `Date` that keeps up with the wall clock while the calendar is mounted. */
export function useNow(): Date {
  return React.useSyncExternalStore(
    subscribeNow,
    () => now,
    () => now
  )
}

/* ── The event the reader last reached for ─────────────────────────────── */

let activeEventId: string | number = ""
const activeListeners = new Set<() => void>()

export function setActiveEvent(id: string | number) {
  activeEventId = id
  activeListeners.forEach((l) => l())
}

export function getActiveEvent() {
  return activeEventId
}

export function useActiveEvent(): string | number {
  return React.useSyncExternalStore(
    (l) => {
      activeListeners.add(l)
      return () => activeListeners.delete(l)
    },
    () => activeEventId,
    () => activeEventId
  )
}

/* ── Whether any event popover is open ─────────────────────────────────── */

export const popoverGate = { open: false }

/* ── Splitting events between the time grid and the all-day row ────────── */

export function useEventData(
  events: CalendarEvent[] | undefined,
  minuteHeight?: number
) {
  return React.useMemo(() => {
    const list = events ?? []
    const grouped: GroupedCalendarEvents = {}
    for (const event of list) {
      if (isAllDayLike(event)) continue
      for (const segment of daySegments(event)) {
        segment.startTime = calculateMinutes(segment.segFromTime)
        segment.endTime = calculateMinutes(segment.segToTime)
        ;(grouped[segment.date] ||= []).push(segment)
      }
    }
    for (const [date, segments] of Object.entries(grouped)) {
      grouped[date] = findOverlappingEventsCount(segments, minuteHeight)
    }
    const allDayEvents = list.filter(isAllDayLike)
    return { timedEvents: grouped, allDayEvents }
  }, [events, minuteHeight])
}

/* ── What the Day and Week views share about their hours ───────────────── */

export function useHourGrid(
  config: EventConfig,
  grid: React.RefObject<HTMLElement | null>
) {
  const hourHeight = config.hourHeight
  const minuteHeight = hourHeight / 60
  const timeArray =
    config.timeFormat === "24h" ? twentyFourHoursFormat : twelveHoursFormat

  const LAST_START = 23 * 60 + 30

  /**
   * The time a click asks for: the mark it landed nearest, less the half
   * hour that puts that mark in the middle of the event rather than at its
   * start. Half hours, not quarters.
   */
  const slotTime = React.useCallback(
    (e: React.MouseEvent, hour: number): string => {
      const row = e.currentTarget as HTMLElement | null
      const fraction = row
        ? (e.clientY - row.getBoundingClientRect().top) / hourHeight
        : 0
      const minutes = fraction < 0.25 ? 0 : fraction < 0.75 ? 30 : 60
      const start = Math.min(Math.max(hour * 60 + minutes - 30, 0), LAST_START)
      const startHour = Math.floor(start / 60)
      if (start % 60 === 0) return timeArray[startHour]
      if (config.timeFormat === "24h")
        return `${String(startHour).padStart(2, "0")}:30`
      return `${((startHour + 11) % 12) + 1}:30 ${startHour < 12 ? "am" : "pm"}`
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [hourHeight, config.timeFormat]
  )

  const scrolled = React.useRef(false)
  React.useEffect(() => {
    if (scrolled.current) return
    scrolled.current = true
    const scrollToHour = config.scrollToHour || new Date().getHours()
    grid.current?.scrollBy(0, scrollToHour * 60 * minuteHeight - 10)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  return { hourHeight, minuteHeight, timeArray, slotTime }
}

/* ── Keeping a scrolling strip of dated rows in step with navigation ───── */

export function useStripScroll(
  scroller: React.RefObject<HTMLElement | null>,
  target: Date | undefined,
  jump?: Date | undefined
) {
  const rows = React.useCallback(
    () =>
      Array.from(
        scroller.current?.querySelectorAll<HTMLElement>("[data-strip-date]") ??
          []
      ),
    [scroller]
  )

  const rowFor = React.useCallback(
    (date: string): HTMLElement | undefined => {
      let found: HTMLElement | undefined
      for (const row of rows()) {
        const start = row.dataset.stripDate!
        if (start === date) return row
        if (start < date) found = row
        else break
      }
      return found
    },
    [rows]
  )

  const scrollToDate = React.useCallback(
    (date: Date | string) => {
      const d = typeof date === "string" ? new Date(date) : date
      const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`
      const row = rowFor(key)
      const el = scroller.current
      if (row && el) el.scrollTop = row.offsetTop
    },
    [rowFor, scroller]
  )

  const targetKey = target ? target.toDateString() : ""
  const jumpKey = jump ? jump.getTime() : 0
  const first = React.useRef(true)
  React.useEffect(() => {
    if (first.current) {
      first.current = false
      scrollToDate(target ?? new Date())
      return
    }
    if (target) scrollToDate(target)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [targetKey, jumpKey])

  return { scrollToDate }
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { useEventContext } from "./context"
import { EventPopover } from "./event-popover"
import { NewEventModal } from "./event-modal"
