const NARROW_LIST = 640

/** One listed event in the Agenda, read as a row rather than a pill. */
function EventAgendaRow({
  event,
  date,
  narrow,
  slots,
}: {
  event: CalendarEvent
  date: Date
  narrow?: boolean
  slots: EventSlots
}) {
  const context = useEventContext("EventAgendaRow")
  const {
    config,
    actions,
    bgStyle,
    isActive,
    markActive,
    handleEventClick,
    handleEventEdit,
    handleEventDelete,
    registerDeleteShortcut,
    unregisterDeleteShortcut,
  } = useEventBase(event)
  void context

  const [isPopoverOpen, setPopoverOpen] = React.useState(false)
  const now = useNow()

  const timeLabel = rowTimeLabel(event, config.timeFormat, date)
  const description = rowDescription(event, date)
  const timing = rowTiming(event, date, now)
  const isPast = hasEnded(event, date, now)

  const slotProps: EventRowSlotProps = {
    calendarEvent: event,
    date,
    description,
    timing,
  }

  const hasDescription = !!description || !!slots.eventDescription
  const hasParticipant = !!slots.eventParticipant

  const togglePopover = () => setPopoverOpen((o) => !o)

  function onKeydown(e: React.KeyboardEvent) {
    if (e.key !== "Enter" && e.key !== " ") return
    e.preventDefault()
    markActive()
    if (actions.props.onEventClick) {
      actions.props.onEventClick({
        e: e as unknown as KeyboardEvent,
        calendarEvent: event,
      })
    } else togglePopover()
  }

  return (
    <EventPopover
      open={isPopoverOpen}
      onOpenChange={setPopoverOpen}
      side="bottom"
      calendarEvent={event}
      date={date}
      onOpen={registerDeleteShortcut}
      onClose={unregisterDeleteShortcut}
      onEdit={handleEventEdit}
      onDelete={handleEventDelete}
    >
      <div
        className={cn(
          "event calendar-row flex w-full gap-1.5 rounded-[8px] pr-3 pl-1.5 text-left",
          narrow ? "narrow py-2.5" : "py-1.5",
          isActive && "active",
          isPast && "past",
          !!event.isDraft && "event-draft"
        )}
        style={{ ...bgStyle, width: "100%" }}
        role="button"
        tabIndex={0}
        onClick={(e) => {
          e.preventDefault()
          e.stopPropagation()
          handleEventClick(e, togglePopover, isPopoverOpen)
        }}
        onDoubleClick={(e) => {
          e.preventDefault()
          handleEventEdit(e)
        }}
        onKeyDown={onKeydown}
      >
        <span
          className={cn(
            "event-border my-px w-[2px] shrink-0 self-stretch rounded-[8px]",
            event.isDraft && "invisible"
          )}
        />
        <div
          className={cn(
            "flex min-w-0 flex-1",
            narrow ? "items-center gap-3" : "items-baseline gap-2.5"
          )}
        >
          {!narrow && (
            <span className="calendar-row-time w-[132px] shrink-0 text-[12px]/[1.35] whitespace-nowrap tabular-nums text-[color:var(--ec-ink-gray-7)]">
              {timeLabel}
            </span>
          )}
          <span
            className={cn(
              "flex min-w-0 flex-1",
              narrow ? "flex-col gap-0.5" : "items-baseline gap-2"
            )}
          >
            <span
              className={cn(
                narrow ? "flex min-w-0 items-baseline gap-2" : "contents"
              )}
            >
              <span
                className={cn(
                  // The size carries its own 20px line: a bare `leading-5`
                  // beside it is merged away, and 13px on a 14.95 line box
                  // let truncate slice the descender off a g or a y.
                  "calendar-row-title truncate",
                  narrow
                    ? "min-w-0 text-[14px]/5 font-medium"
                    : "shrink-0 text-[13px]/5 font-medium",
                  event.isDeclined &&
                    "text-[color:var(--ec-ink-gray-5)]! line-through"
                )}
              >
                {event.title || "[No title]"}
              </span>
              {!narrow && hasDescription ? (
                <span className="calendar-row-description event-subtitle min-w-0 truncate text-[12px] leading-4">
                  {slots.eventDescription
                    ? slots.eventDescription(slotProps)
                    : description}
                </span>
              ) : null}
              <span className="flex shrink-0 items-center gap-1 empty:hidden">
                {slots.eventSuffix ? slots.eventSuffix(slotProps) : null}
              </span>
            </span>
            {narrow ? (
              <span className="event-subtitle flex min-w-0 items-baseline gap-1.5 text-[13px] leading-4">
                <span className="calendar-row-time shrink-0 whitespace-nowrap tabular-nums text-[color:var(--ec-ink-gray-7)]">
                  {timeLabel}
                </span>
                {hasDescription ? (
                  <span className="calendar-row-description min-w-0 truncate">
                    {slots.eventDescription
                      ? slots.eventDescription(slotProps)
                      : description}
                  </span>
                ) : null}
              </span>
            ) : null}
          </span>
          {hasParticipant ? (
            <span className="calendar-row-participant event-subtitle flex shrink-0 items-center gap-1.5 self-center text-[12px] leading-4 whitespace-nowrap">
              {slots.eventParticipant!(slotProps)}
            </span>
          ) : null}
        </div>
      </div>
    </EventPopover>
  )
}

/** Three months as a list of weeks, each week a card of its days. */
export function EventAgenda({
  events,
  anchor,
  jump,
  loading,
  slots,
}: {
  events: CalendarEvent[]
  /** The day the list runs from. */
  anchor: Date
  /** Bumped each time the calendar is told to go to a date. */
  jump?: number
  loading?: boolean
  slots: EventSlots
}) {
  const { actions } = useEventContext("EventAgenda")
  const scroller = React.useRef<HTMLDivElement | null>(null)
  const [listWidth, setListWidth] = React.useState(0)

  React.useEffect(() => {
    const el = scroller.current
    if (!el || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(([entry]) =>
      setListWidth(entry?.contentRect.width ?? 0)
    )
    observer.observe(el)
    return () => observer.disconnect()
  }, [])

  const isNarrow = !!listWidth && listWidth < NARROW_LIST

  const now = useNow()
  const weeks = React.useMemo(
    () => agendaWeeks(events, anchor, now),
    [events, anchor, now]
  )
  const isEmpty = !weeks.length

  const anchoredOnThisMonth =
    anchor.getFullYear() === now.getFullYear() &&
    anchor.getMonth() === now.getMonth()

  const spanKey = `${anchor.getFullYear()}-${anchor.getMonth()}|${jump ?? 0}`
  const positionKey = `${spanKey}|${isNarrow}`
  const positionedFor = React.useRef("")

  const openMargin = isNarrow ? 16 : 0

  const positionList = React.useCallback(() => {
    const box = scroller.current
    if (!box) return
    if (!weeks.length) return
    if (!listWidth) return

    positionedFor.current = positionKey
    if (!anchoredOnThisMonth) {
      box.scrollTop = 0
      return
    }

    const todayKey = parseDate(now)
    const target = Array.from(
      box.querySelectorAll<HTMLElement>("[data-strip-date]")
    ).find((el) => (el.dataset.stripDate ?? "") >= todayKey)
    if (!target) return

    const previous =
      target.previousElementSibling ??
      target.parentElement?.previousElementSibling
    const top = previous?.hasAttribute("data-strip-week") ? previous : target

    box.scrollTop +=
      top.getBoundingClientRect().top -
      box.getBoundingClientRect().top -
      openMargin
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [weeks.length, listWidth, positionKey, anchoredOnThisMonth, openMargin])

  React.useEffect(() => {
    if (positionedFor.current === positionKey) return
    const frame = requestAnimationFrame(positionList)
    return () => cancelAnimationFrame(frame)
  }, [positionKey, positionList, weeks.length, listWidth])

  /** Which week labels are stuck to the top of the list, for the fade. */
  const onScroll = React.useCallback(() => {
    const list = scroller.current
    if (!list) return
    const top = list.getBoundingClientRect().top
    for (const label of list.querySelectorAll<HTMLElement>(
      ".calendar-week-label"
    )) {
      const r = label.getBoundingClientRect()
      const stuck = r.top <= top + 0.5 && r.bottom > top
      if (stuck) label.setAttribute("data-stuck", "")
      else label.removeAttribute("data-stuck")
    }
  }, [])

  const spanLabel = (() => {
    const { start, end } = agendaMonths(anchor)
    const name = (d: Date) => monthList[d.getMonth()]
    return start.getFullYear() === end.getFullYear()
      ? `${name(start)} and ${name(end)}`
      : `${name(start)} ${start.getFullYear()} and ${name(end)} ${end.getFullYear()}`
  })()

  const openDay = (date: Date) => {
    actions.setCalendarDate(date)
    actions.updateActiveView("Day", date)
  }

  const openWeek = (start: Date) => {
    actions.setCalendarDate(start)
    requestAnimationFrame(() => actions.updateActiveView("Week", start))
  }

  const weekday = (date: Date) => daysListFull[date.getDay()]

  const dayLabel = (row: AgendaRow) => {
    const date = `${row.date.getDate()} ${shortMonth(row.date)}`
    return row.isToday ? `${daysList[row.date.getDay()]}, ${date}` : date
  }

  const weekName = (week: AgendaWeek) => {
    if (week.isCurrent) return "This week"
    if (week.isNext) return "Next week"
    if (week.isPrevious) return "Last week"
    return null
  }

  return (
    <div
      ref={scroller}
      onScroll={onScroll}
      className={cn(
        "ec-agenda flex min-h-0 flex-1 flex-col overflow-y-auto bg-[color:var(--ec-surface-base)]",
        !isNarrow && "pb-5 pl-5 pr-5"
      )}
    >
      {isEmpty && loading ? (
        <div className="flex justify-center p-10">
          <Spinner className="size-6 text-[color:var(--ec-ink-gray-4)]" />
        </div>
      ) : isEmpty ? (
        <p className="p-10 text-center text-[13px] text-[color:var(--ec-ink-gray-4)]">
          Nothing on between {spanLabel}.
        </p>
      ) : (
        <div className={cn("flex flex-col gap-5", isNarrow && "px-4 pb-4")}>
          {weeks.map((week) => (
            <div key={week.key}>
              {/* The week's heading: a link, sticky while its week is in view. */}
              <button
                type="button"
                data-strip-week=""
                className={cn(
                  "calendar-week-label sticky top-0 z-[2] flex w-full cursor-pointer bg-[color:var(--ec-surface-base)] pb-3 text-[color:var(--ec-ink-gray-8)] hover:text-[color:var(--ec-ink-gray-6)]",
                  week.isPast && "past",
                  isNarrow
                    ? "flex-col items-start gap-0.5 pt-1.5 pl-3.5 text-[16px] font-semibold"
                    : "items-baseline gap-2 pt-1.5 pl-[4px] text-[14px] font-medium"
                )}
                onClick={() => openWeek(week.start)}
              >
                {weekName(week) ?? agendaRangeLabel(week.start, week.end)}
                {weekName(week) ? (
                  <span
                    className={cn(
                      isNarrow
                        ? "text-[13px] font-[420] text-[color:var(--ec-ink-gray-5)]"
                        : "text-[12px] font-[420] text-[color:var(--ec-ink-gray-4)]"
                    )}
                  >
                    {agendaRangeLabel(week.start, week.end)}
                  </span>
                ) : null}
                <ChevronRightIcon className="size-4 self-center text-[color:var(--ec-ink-gray-5)]" />
              </button>

              <div
                className={cn(
                  isNarrow
                    ? "flex flex-col gap-4"
                    : "overflow-hidden rounded-[10px] border border-[color:var(--ec-outline-gray-1)] bg-[color:var(--ec-surface-base)]"
                )}
              >
                {week.days.map((row, index) => (
                  <div
                    key={row.key}
                    data-strip-date={row.key}
                    data-today={row.isToday || undefined}
                    className={cn(
                      "flex",
                      isNarrow && "flex-col gap-1",
                      index &&
                        !isNarrow &&
                        "border-t border-[color:var(--ec-outline-gray-1)]"
                    )}
                  >
                    <button
                      type="button"
                      className={cn(
                        "calendar-day-header flex shrink-0 cursor-pointer items-baseline gap-2 text-left",
                        isNarrow
                          ? "px-3.5 py-1"
                          : "m-1.5 w-[168px] rounded-[6px] px-2 py-1.5",
                        row.isPast && "past"
                      )}
                      onClick={() => openDay(row.date)}
                    >
                      <span
                        className={cn(
                          "shrink-0 text-[color:var(--ec-ink-gray-8)]",
                          isNarrow
                            ? "text-[14px]/5 font-medium"
                            : "text-[13px]/5 font-medium"
                        )}
                      >
                        {slots.agendaDayLabel
                          ? slots.agendaDayLabel(row.date, row.isToday).primary
                          : row.isToday
                            ? "Today"
                            : weekday(row.date)}
                      </span>
                      <span className="min-w-0 truncate text-[13px] leading-5 text-[color:var(--ec-ink-gray-5)]">
                        {slots.agendaDayLabel
                          ? slots.agendaDayLabel(row.date, row.isToday).secondary
                          : dayLabel(row)}
                      </span>
                    </button>

                    <div
                      className={cn(
                        "flex min-w-0 flex-1 flex-col gap-1",
                        !isNarrow && "py-1.5 pr-1.5"
                      )}
                    >
                      {row.events.map((event) => (
                        <EventAgendaRow
                          key={String(event.id ?? event.name)}
                          event={event}
                          date={row.date}
                          narrow={isNarrow}
                          slots={slots}
                        />
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { useEventContext } from "./context"
import { EventGridPill } from "./grid-pill"
import { EventTimeMarker } from "./time-marker"
import { useEventData, useHourGrid } from "./hooks"
import { MORE_BUTTON_CLASS, parseDate } from "./utils"
import { PILL_INSET, PILL_MARGIN, eventDays } from "./span"
import type { CalendarEvent, EventConfig } from "./types"

/** The lane's own `gap-x-1`, in pixels — the space between two pills. */
const LANE_GAP = 4

export function EventDaily({
  events,
  currentDate,
  config,
}: {
  events: CalendarEvent[]
  currentDate: Date
  config: EventConfig
}) {
  const { actions } = useEventContext("EventDaily")
  const gridRef = React.useRef<HTMLDivElement | null>(null)
  const { hourHeight, minuteHeight, timeArray, slotTime } = useHourGrid(
    config,
    gridRef
  )
  const { timedEvents, allDayEvents } = useEventData(events, minuteHeight)

  const pillInset = PILL_INSET
  const [isCollapsed, setCollapsed] = React.useState(true)

  const dayFullDayEvents = React.useMemo(() => {
    const day = parseDate(currentDate)
    return allDayEvents.filter((event) => {
      const { start, end } = eventDays(event)
      return start <= day && day <= end
    })
  }, [allDayEvents, currentDate])

  /** How many all-day pills fit on one line; -1 when everything fits. */
  const [laneFits, setLaneFits] = React.useState(-1)
  const [measuring, setMeasuring] = React.useState(true)
  const allDayLane = React.useRef<HTMLDivElement | null>(null)
  const laneWidth = React.useRef(0)

  const measureLane = React.useCallback(() => {
    const lane = allDayLane.current
    if (!lane) return
    const nodes = Array.from(lane.children).filter(
      (node): node is HTMLElement => node instanceof HTMLElement
    )
    const more = nodes.find((node) => node.matches("[data-all-day-more]")) ?? null
    const pills = nodes
      .filter((node) => node !== more)
      .map((pill) => pill.offsetWidth)
    const style = getComputedStyle(lane)
    const width =
      lane.clientWidth -
      parseFloat(style.paddingLeft) -
      parseFloat(style.paddingRight)

    if (width <= 0) {
      requestAnimationFrame(measureLane)
      return
    }

    setMeasuring(false)
    laneWidth.current = width
    if (!pills.length) return

    const whole = pills.reduce((sum, pill, i) => sum + pill + (i ? LANE_GAP : 0), 0)
    if (whole <= width) {
      setLaneFits(-1)
      return
    }

    const room = width - ((more?.offsetWidth ?? 0) + LANE_GAP)
    let used = 0
    let fits = 0
    for (const pill of pills) {
      const next = used + pill + (fits ? LANE_GAP : 0)
      if (next > room) break
      used = next
      fits++
    }
    setLaneFits(Math.max(fits, 1))
  }, [])

  const dayKey = parseDate(currentDate)
  const eventsKey = dayFullDayEvents.map((e) => e.id).join("|")
  // Another day, or other events on it: fold the lane and measure again. Not
  // on mount — the lane is already measuring, and setting it again there
  // landed after the first measure had finished, leaving it measuring for
  // good with "+0 more" in an empty lane.
  const laneKey = `${dayKey}/${eventsKey}`
  const measuredKey = React.useRef(laneKey)
  React.useEffect(() => {
    if (measuredKey.current === laneKey) return
    measuredKey.current = laneKey
    setCollapsed(true)
    setMeasuring(true)
  }, [laneKey])

  React.useLayoutEffect(() => {
    if (measuring) measureLane()
  }, [measuring, measureLane])

  React.useEffect(() => {
    const lane = allDayLane.current
    if (!lane || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(([entry]) => {
      const width = entry?.contentRect.width ?? 0
      if (Math.abs(width - laneWidth.current) < 1) return
      laneWidth.current = width
      setMeasuring(true)
    })
    observer.observe(lane)
    return () => observer.disconnect()
  }, [])

  const shownFullDayEvents =
    measuring || !isCollapsed || laneFits < 0
      ? dayFullDayEvents
      : dayFullDayEvents.slice(0, laneFits)
  const hiddenFullDayEvents = dayFullDayEvents.length - shownFullDayEvents.length

  return (
    <div
      className={cn(
        "flex flex-1 flex-col overflow-y-auto border-[color:var(--ec-outline-gray-1)]",
        config.noBorder ? "" : "rounded-[12px] border"
      )}
    >
      {/* All-day lane */}
      <div
        className={cn(
          "flex h-fit min-h-[34px] shrink-0",
          !config.noBorder && "border-b border-[color:var(--ec-outline-gray-1)]"
        )}
      >
        <div className="flex w-[72px] shrink-0 justify-center border-r border-[color:var(--ec-outline-gray-1)] pt-1 pl-px">
          <div className="ml-auto mr-[9px] inline-flex leading-[18px] h-7 items-center text-[12px] font-[420] text-[color:var(--ec-ink-gray-8)]">
            All day
          </div>
        </div>
        <div
          ref={allDayLane}
          data-all-day-lane=""
          className={cn(
            "flex w-full flex-wrap gap-x-1 gap-y-1 overflow-hidden py-1",
            measuring && "max-h-10"
          )}
          style={{ paddingInline: `${pillInset - PILL_MARGIN}px` }}
          data-date-attr={String(currentDate)}
          onClick={(e) => {
            e.preventDefault()
            actions.handleCellClick(e, currentDate, "", true)
          }}
        >
          {shownFullDayEvents.map((calendarEvent, idx) => (
            <EventGridPill
              key={String(calendarEvent.id)}
              event={{ ...calendarEvent, idx }}
              date={currentDate}
            />
          ))}
          {hiddenFullDayEvents || measuring ? (
            <Button
              variant="ghost"
              size="xs"
              data-all-day-more=""
              className={cn(
                MORE_BUTTON_CLASS,
                "mx-px min-h-7 w-fit shrink-0 self-stretch px-2"
              )}
              onClick={(e) => {
                e.stopPropagation()
                setCollapsed(false)
              }}
            >
              {`+${hiddenFullDayEvents || dayFullDayEvents.length} more`}
            </Button>
          ) : null}
        </div>
      </div>
      <div className="h-full overflow-hidden">
        <div
          ref={gridRef}
          className={cn(
            "flex h-full w-full overflow-scroll",
            config.noBorder && "border-t border-[color:var(--ec-outline-gray-1)]"
          )}
        >
          <div
            className="w-[72px] shrink-0 self-start border-r border-[color:var(--ec-outline-gray-1)]"
            style={{ height: `${24 * hourHeight}px` }}
          />
          <div className="grid h-full w-full grid-cols-1 pb-2">
            <div className="calendar-column relative" data-time-grid="">
              {timeArray.map((time, i) => (
                <div
                  key={time}
                  className="relative flex"
                  data-time-attr={i === 0 ? "" : time}
                  onClick={(e) =>
                    actions.handleCellClick(e, currentDate, slotTime(e, i))
                  }
                >
                  <div
                    className={cn(
                      "w-full",
                      i !== timeArray.length - 1 &&
                        "border-b border-[color:var(--ec-outline-gray-1)]"
                    )}
                    style={{ height: `${hourHeight}px` }}
                  />
                </div>
              ))}
              {(timedEvents[parseDate(currentDate)] ?? []).map((calendarEvent) => (
                <EventGridPill
                  key={String(calendarEvent.id)}
                  event={calendarEvent}
                  date={currentDate}
                  inset={pillInset}
                />
              ))}
              <EventTimeMarker date={currentDate} />
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { useEventContext } from "./context"
import { EventMonthPill } from "./month-pill"
import { useNow, useStripScroll } from "./hooks"
import { MORE_BUTTON_CLASS, daysList, parseDate } from "./utils"
import {
  COLUMN_INSET,
  COLUMN_RULE,
  barsInColumn,
  dayEvents,
  daysBetween,
  isSpan,
  layoutRow,
  shiftEventDays,
  weekLaneHeight,
  weekLanePitch,
} from "./span"
import { shortMonth, stripWeeks } from "./month-strip"
import type { CalendarEvent, EventConfig, EventRowBar } from "./types"

/** The date-number strip at the top of every cell. */
const HEADER_HEIGHT = 28
const CELL_INSET = 4
const MIN_CELL_ROWS = 3
const CELL_PAD = 6
/** A week row's floor: a day at its fullest — three rows and the "N more". */
const ROW_FLOOR = 159

interface StripRow {
  key: string
  week: Date[]
  bars: EventRowBar[]
  days: CalendarEvent[][]
  lanes: number[]
}

export function EventMonthly({
  events,
  currentMonth,
  currentYear,
  currentDate,
  jumpDate,
  config,
}: {
  events: CalendarEvent[]
  currentMonth: number
  currentYear: number
  currentDate?: Date
  jumpDate?: Date
  config: EventConfig
}) {
  const { actions } = useEventContext("EventMonthly")
  const scroller = React.useRef<HTMLDivElement | null>(null)
  const [isNarrow, setNarrow] = React.useState(false)
  const [rowHeight, setRowHeight] = React.useState(0)

  const laneHeight = weekLaneHeight(isNarrow)
  const lanePitch = weekLanePitch(isNarrow)
  const cellInset = isNarrow ? COLUMN_INSET : CELL_INSET

  const rows = React.useMemo<StripRow[]>(() => {
    const spans = events.filter(isSpan)
    return stripWeeks(currentMonth, currentYear).map((week) => {
      const { bars } = layoutRow(spans, week)
      return {
        key: parseDate(week[0]),
        week,
        bars,
        days: week.map((date) => dayEvents(events, date)),
        lanes: week.map((_, col) => {
          const inColumn = barsInColumn(bars, col)
          return inColumn.length
            ? Math.max(...inColumn.map((bar) => bar.lane)) + 1
            : 0
        }),
      }
    })
  }, [events, currentMonth, currentYear])

  React.useEffect(() => {
    const el = scroller.current
    if (!el || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(([entry]) => {
      const width = entry?.contentRect.width ?? 0
      setNarrow(!!width && width / 7 < 90)
      setRowHeight((entry?.contentRect.height ?? 0) / Math.max(rows.length, 1))
    })
    observer.observe(el)
    return () => observer.disconnect()
  }, [rows.length])

  /** How many rows a cell can draw under its date. */
  const cellCapacity = React.useMemo(() => {
    if (!isNarrow) return MIN_CELL_ROWS
    const room = rowHeight - HEADER_HEIGHT - CELL_PAD
    const gap = lanePitch - laneHeight
    return Math.max(Math.floor((room + gap) / lanePitch), MIN_CELL_ROWS)
  }, [isNarrow, rowHeight, lanePitch, laneHeight])

  const cellEvents = React.useCallback(
    (row: StripRow, col: number, laneLimit: number) => {
      const days = row.days[col] ?? []
      const lanes = Math.min(row.lanes[col] ?? 0, laneLimit)
      const hiddenBars = barsInColumn(row.bars, col).filter(
        (bar) => bar.lane >= laneLimit
      ).length
      const room = Math.max(cellCapacity - lanes, 0)
      if (!hiddenBars && days.length <= room)
        return { shown: days, hidden: 0, lanes }
      // Wide, a cell keeps its three and says how many more on a line of its
      // own under them — the week's floor has room for it — so six events
      // read as three and "3 more". Narrow, the count takes one of the rows.
      const shown = isNarrow ? Math.max(room - 1, 0) : room
      return {
        shown: days.slice(0, shown),
        hidden: days.length - shown + hiddenBars,
        lanes,
      }
    },
    [cellCapacity, isNarrow]
  )

  const laidOut = React.useMemo(
    () =>
      rows.map((row) => {
        const maxLanes = row.lanes.length ? Math.max(...row.lanes) : 0
        const fits = (limit: number) =>
          row.week.every((_, col) => {
            const lanes = Math.min(row.lanes[col] ?? 0, limit)
            const dropped = (row.lanes[col] ?? 0) > limit
            const needsRow = dropped || !!row.days[col]?.length
            return lanes + (needsRow ? 1 : 0) <= cellCapacity
          })
        let laneLimit = maxLanes
        if (isNarrow) while (laneLimit > 0 && !fits(laneLimit)) laneLimit--
        return {
          ...row,
          shownBars: row.bars.filter((bar) => bar.lane < laneLimit),
          cells: row.week.map((_, col) => cellEvents(row, col, laneLimit)),
        }
      }),
    [rows, cellCapacity, cellEvents, isNarrow]
  )

  const now = useNow()
  const isToday = (date: Date) => parseDate(date) === parseDate(now)
  const dayLabel = (date: Date) =>
    date.getDate() === 1 && !isToday(date)
      ? `${shortMonth(date)} 1`
      : String(date.getDate())

  const openDay = (date: Date) => {
    actions.setCalendarDate(date)
    actions.updateActiveView("Day", date)
  }

  useStripScroll(scroller, currentDate, jumpDate)

  function barStyle(bar: EventRowBar): React.CSSProperties {
    const span = bar.endCol - bar.startCol + 1
    return {
      left: `calc(${(bar.startCol / 7) * 100}% + ${cellInset}px)`,
      width: `calc(${(span / 7) * 100}% - ${cellInset * 2 + COLUMN_RULE}px)`,
      top: `${HEADER_HEIGHT + bar.lane * lanePitch}px`,
      height: `${laneHeight}px`,
    }
  }

  /* ── Drag to move ─────────────────────────────────────────────────────── */

  const [draggingId, setDraggingId] = React.useState<CalendarEvent["id"] | null>(
    null
  )

  /**
   * The bar the pointer is on, as an event: a stay across weeks is one piece
   * per row, and pointing at any of them should light the whole of it —
   * :hover only ever knows the piece.
   */
  const [hoverId, setHoverId] = React.useState<CalendarEvent["id"] | null>(null)

  function dateAtPointer(row: HTMLElement, clientX: number, week: Date[]) {
    const rect = row.getBoundingClientRect()
    const col = Math.floor(((clientX - rect.left) / rect.width) * 7)
    return parseDate(week[Math.max(0, Math.min(6, col))])
  }

  const onDragStart =
    (calendarEvent: CalendarEvent, week: Date[]) => (event: React.DragEvent) => {
      if (!calendarEvent.id) return
      setDraggingId(calendarEvent.id)
      const target = event.target as HTMLElement | null
      if (target) target.style.cursor = "move"
      if (!event.dataTransfer) return
      const row = target?.closest("[data-week-row]") as HTMLElement | null
      event.dataTransfer.dropEffect = "move"
      event.dataTransfer.effectAllowed = "move"
      event.dataTransfer.setData("calendarEventID", String(calendarEvent.id))
      event.dataTransfer.setData(
        "calendarGrabDate",
        row ? dateAtPointer(row, event.clientX, week) : parseDate(week[0])
      )
    }

  const onDrop = (week: Date[]) => (event: React.DragEvent) => {
    const calendarEventID = event.dataTransfer?.getData("calendarEventID")
    const grabDate = event.dataTransfer?.getData("calendarGrabDate")
    if (!calendarEventID || !grabDate) return
    const target = event.target as HTMLElement | null
    if (target) target.style.cursor = "default"
    const calendarEvent = events.find((e) => String(e.id) === calendarEventID)
    if (!calendarEvent) return
    const dropDate = dateAtPointer(
      event.currentTarget as HTMLElement,
      event.clientX,
      week
    )
    const shift = daysBetween(grabDate, dropDate)
    if (!shift) return
    actions.updateEventState(shiftEventDays({ ...calendarEvent }, shift))
  }

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <div className="grid w-full grid-cols-7">
        {daysList.map((day) => (
          <span
            key={day}
            className={cn(
              "inline-flex h-8 items-center justify-center text-[color:var(--ec-ink-gray-6)]",
              isNarrow ? "text-[13px]" : "text-[14px]"
            )}
          >
            {day}
          </span>
        ))}
      </div>

      <div
        ref={scroller}
        className={cn(
          "relative -mt-px min-h-0 flex-1 overflow-y-auto border-[color:var(--ec-outline-gray-1)]",
          config.noBorder ? "border-t" : "rounded-[12px] border"
        )}
      >
        <div className="flex min-h-full flex-col">
          {laidOut.map((row) => (
            <div
              key={row.key}
              className="relative grid min-h-[159px] flex-1 basis-0 grid-cols-7 border-b border-[color:var(--ec-outline-gray-1)] select-none last:border-b-0"
              style={{ minHeight: `${ROW_FLOOR}px` }}
              data-strip-date={row.key}
              data-week-row=""
              onDragOver={(e) => e.preventDefault()}
              onDragEnter={(e) => e.preventDefault()}
              onDrop={onDrop(row.week)}
            >
              {row.week.map((date, col) => (
                <div
                  key={parseDate(date)}
                  className={cn(
                    "flex min-w-0 flex-col border-[color:var(--ec-outline-gray-1)]",
                    col > 0 && "border-l"
                  )}
                  onClick={(e) => actions.handleCellClick(e, date)}
                >
                  <div
                    className={cn(
                      "flex shrink-0 items-center px-[3px] text-[12px]",
                      isNarrow ? "justify-center" : "justify-end"
                    )}
                    style={{ height: `${HEADER_HEIGHT}px` }}
                  >
                    <button
                      type="button"
                      className={cn(
                        "flex h-6 min-w-6 cursor-pointer items-center justify-center rounded-full px-1.5 whitespace-nowrap",
                        isToday(date)
                          ? "bg-[color:var(--ec-surface-red-7)] text-white"
                          : "text-[color:var(--ec-ink-gray-8)] hover:bg-[color:var(--ec-surface-gray-2)]"
                      )}
                      onClick={(e) => {
                        e.stopPropagation()
                        openDay(date)
                      }}
                    >
                      {dayLabel(date)}
                    </button>
                  </div>

                  {row.cells[col].lanes ? (
                    <div
                      className="shrink-0"
                      style={{ height: `${row.cells[col].lanes * lanePitch}px` }}
                    />
                  ) : null}

                  {row.cells[col].shown.length || row.cells[col].hidden ? (
                    <div
                      className={cn(
                        "flex flex-col pb-1.5",
                        isNarrow ? "gap-0.5" : "gap-1"
                      )}
                      style={{ paddingInline: `${cellInset}px` }}
                    >
                      {row.cells[col].shown.map((event) => (
                        <EventMonthPill
                          key={String(event.id)}
                          event={event}
                          date={date}
                          dense={isNarrow}
                          className={cn(
                            "cursor-pointer",
                            draggingId === event.id && "opacity-40"
                          )}
                          draggable={config.isEditMode}
                          onDragStart={onDragStart(event, row.week)}
                          onDragEnd={() => setDraggingId(null)}
                        />
                      ))}
                      {row.cells[col].hidden ? (
                        isNarrow ? (
                          // Narrow, the count alone — "more" truncated to an
                          // ellipsis in a column this tight — and the way to
                          // the day, where the whole of it fits.
                          <Button
                            variant="ghost"
                            size="xs"
                            className={cn(MORE_BUTTON_CLASS, "w-full px-0")}
                            style={{ height: `${laneHeight}px` }}
                            onClick={(e) => {
                              e.stopPropagation()
                              openDay(date)
                            }}
                          >
                            {`+${row.cells[col].hidden}`}
                          </Button>
                        ) : (
                          <div
                            className="flex h-7 items-center px-1.5 text-[12px] text-[color:var(--ec-ink-gray-7)]"
                            style={{ height: `${laneHeight}px` }}
                          >
                            {row.cells[col].hidden} more
                          </div>
                        )
                      ) : null}
                    </div>
                  ) : null}
                </div>
              ))}

              {row.shownBars.map((bar) => (
                <EventMonthPill
                  key={String(bar.event.id)}
                  event={bar.event}
                  date={row.week[bar.startCol]}
                  bar={bar}
                  dense={isNarrow}
                  className={cn(
                    "absolute cursor-pointer",
                    draggingId === bar.event.id && "opacity-40",
                    hoverId != null &&
                      hoverId === bar.event.id &&
                      "ec-hover-all"
                  )}
                  style={barStyle(bar)}
                  draggable={config.isEditMode}
                  onDragStart={onDragStart(bar.event, row.week)}
                  onDragEnd={() => setDraggingId(null)}
                  onMouseEnter={() => setHoverId(bar.event.id ?? null)}
                  onMouseLeave={() =>
                    setHoverId((id) => (id === bar.event.id ? null : id))
                  }
                />
              ))}
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { useEventContext } from "./context"
import { EventGridPill } from "./grid-pill"
import { EventTimeMarker } from "./time-marker"
import { useEventData, useHourGrid, useNow } from "./hooks"
import { MORE_BUTTON_CLASS, daysList, parseDate } from "./utils"
import {
  COLUMN_INSET,
  PILL_INSET,
  barsInColumn,
  layoutRow,
  weekLaneGap,
  weekLaneHeight,
  weekLanePitch,
} from "./span"
import type { CalendarEvent, EventConfig } from "./types"

const NARROW_COLUMN = 64

/** Past three lanes the all-day row folds to two, with a count. */
const COLLAPSE_ABOVE = 3
const COLLAPSED_LANES = 2

export function EventWeekly({
  events,
  weeklyDates,
  config,
}: {
  events: CalendarEvent[]
  weeklyDates: Date[]
  config: EventConfig
}) {
  const { actions } = useEventContext("EventWeekly")
  const gridRef = React.useRef<HTMLDivElement | null>(null)
  const headRef = React.useRef<HTMLDivElement | null>(null)
  const [isCollapsed, setCollapsed] = React.useState(true)
  const [headWidth, setHeadWidth] = React.useState(0)

  React.useEffect(() => {
    const el = headRef.current
    if (!el || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(([entry]) =>
      setHeadWidth(entry?.contentRect.width ?? 0)
    )
    observer.observe(el)
    return () => observer.disconnect()
  }, [])

  const isNarrow =
    !!headWidth && headWidth / (weeklyDates.length || 7) < NARROW_COLUMN

  const laneHeight = weekLaneHeight(isNarrow)
  const laneGap = weekLaneGap(isNarrow)
  const lanePitch = weekLanePitch(isNarrow)
  const barInset = isNarrow ? COLUMN_INSET : PILL_INSET

  const { hourHeight, minuteHeight, timeArray, slotTime } = useHourGrid(
    config,
    gridRef
  )
  const { timedEvents, allDayEvents } = useEventData(events, minuteHeight)

  const allDayRow = React.useMemo(
    () => layoutRow(allDayEvents, weeklyDates),
    [allDayEvents, weeklyDates]
  )

  const showCollapsable = allDayRow.laneCount > COLLAPSE_ABOVE
  const visibleLanes =
    showCollapsable && isCollapsed ? COLLAPSED_LANES : allDayRow.laneCount
  const visibleBars = allDayRow.bars.filter((bar) => bar.lane < visibleLanes)
  const hiddenCount = (col: number) =>
    barsInColumn(allDayRow.bars, col).filter((bar) => bar.lane >= visibleLanes)
      .length

  const allDayHeight =
    visibleLanes * lanePitch +
    (visibleLanes < allDayRow.laneCount ? laneGap + laneHeight : 0) +
    laneGap

  const now = useNow()
  const isToday = (date: Date) => parseDate(date) === parseDate(now)
  const nowTop = (now.getHours() * 60 + now.getMinutes()) * minuteHeight
  const todayVisible = weeklyDates.some(isToday)

  return (
    <div className="isolate flex flex-1 flex-col overflow-y-auto">
      {/* Day strip: "Sun 17" on one line; today wears the red tag. */}
      <div className="flex">
        <div className="w-[72px] shrink-0" />
        <div ref={headRef} className="grid w-full grid-cols-7">
          {weeklyDates.map((date) => (
            <span
              key={parseDate(date)}
              className={cn(
                "group pointer-events-none relative flex items-center text-center",
                isNarrow
                  ? "h-12 flex-col gap-0.5 pt-1.5 pb-1 text-[12px]"
                  : "h-8 justify-center text-[14px]",
                isToday(date)
                  ? "gap-2 text-[color:var(--ec-ink-gray-7)]"
                  : "gap-1 text-[color:var(--ec-ink-gray-6)]"
              )}
            >
              <span className={cn(isNarrow && "leading-4")}>
                {daysList[date.getDay()]}
              </span>
              <span
                className={cn(
                  "inline-flex items-center justify-center",
                  isToday(date)
                    ? "h-6 w-[26px] rounded-[6px] bg-[color:var(--ec-surface-red-7)] text-white"
                    : ""
                )}
              >
                {date.getDate()}
              </span>
            </span>
          ))}
        </div>
      </div>

      {/* The box: the rule under the strip sits inside its 32px. */}
      <div
        className={cn(
          "-mt-px flex min-h-0 flex-1 flex-col overflow-hidden border-[color:var(--ec-outline-gray-1)]",
          config.noBorder ? "border-t" : "rounded-[12px] border"
        )}
      >
        {/* All-day row: one band, the gutter's rule at its left. */}
        <div className="flex h-fit min-h-[34px] shrink-0 border-b border-[color:var(--ec-outline-gray-1)]">
          <div className="flex w-[72px] shrink-0 justify-center border-r border-[color:var(--ec-outline-gray-1)] pt-1 pl-px">
            <div
              className="ml-auto mr-[9px] inline-flex leading-[18px] items-center text-[12px] font-[420] text-[color:var(--ec-ink-gray-8)]"
              style={{ height: `${laneHeight}px` }}
            >
              All day
            </div>
          </div>
          <div
            className="relative grid w-full grid-cols-7 overflow-hidden py-2"
            style={{ minHeight: `${allDayHeight}px` }}
            data-day-columns="7"
          >
            {weeklyDates.map((date, col) => (
              <div
                key={parseDate(date)}
                className="cell -my-2 flex w-full flex-col"
                data-date-attr={String(date)}
                onClick={(e) => {
                  e.preventDefault()
                  if (hiddenCount(col)) setCollapsed(false)
                  actions.handleCellClick(e, date, "", true)
                }}
              >
                {hiddenCount(col) ? (
                  <Button
                    variant="ghost"
                    size="xs"
                    className={cn(
                      MORE_BUTTON_CLASS,
                      isNarrow ? "self-stretch px-1" : "w-fit justify-start px-2"
                    )}
                    style={{
                      marginTop: `${visibleLanes * lanePitch + laneGap}px`,
                      marginLeft: `${barInset}px`,
                      marginRight: isNarrow ? `${barInset}px` : undefined,
                      height: `${laneHeight}px`,
                    }}
                    onClick={(e) => {
                      e.stopPropagation()
                      setCollapsed(false)
                    }}
                  >
                    {isNarrow ? `+${hiddenCount(col)}` : `+${hiddenCount(col)} more`}
                  </Button>
                ) : null}
              </div>
            ))}
            {visibleBars.map((bar) => (
              <EventGridPill
                key={String(bar.event.id)}
                event={bar.event}
                date={weeklyDates[bar.startCol]}
                bar={bar}
                narrow={isNarrow}
                inset={barInset}
              />
            ))}
          </div>
        </div>

        <div
          ref={gridRef}
          className="relative flex h-full flex-col overflow-auto"
        >
          <div className="flex">
            {/* The hour gutter, a spacer as tall as the 24 hours beside it. */}
            <div
              className="w-[72px] shrink-0 border-r border-[color:var(--ec-outline-gray-1)]"
              style={{ height: `${24 * hourHeight}px` }}
            />

            <div className="relative z-0 flex w-full flex-col">
              <div
                className={cn(
                  "grid w-full grid-cols-7",
                  todayVisible && "ec-week-grid"
                )}
                data-day-columns="7"
                style={
                  todayVisible
                    ? ({ "--now-top": `${Math.round(nowTop)}px` } as React.CSSProperties)
                    : undefined
                }
              >
                {weeklyDates.map((date, idx) => (
                  <div
                    key={parseDate(date)}
                    className={cn(
                      "relative w-full",
                      idx === 0 && "calendar-column",
                      idx !== weeklyDates.length - 1 &&
                        "border-r border-[color:var(--ec-outline-gray-1)]"
                    )}
                    data-date-attr={String(date)}
                    data-time-grid=""
                  >
                    {timeArray.map((time, i) => (
                      <div
                        key={time}
                        className="cell relative flex"
                        data-time-attr={i === 0 ? "" : time}
                        onClick={(e) => {
                          e.preventDefault()
                          actions.handleCellClick(e, date, slotTime(e, i))
                        }}
                      >
                        <div
                          className={cn(
                            "w-full",
                            i !== timeArray.length - 1 &&
                              "border-b border-[color:var(--ec-outline-gray-1)]"
                          )}
                          style={{ height: `${hourHeight}px` }}
                        />
                      </div>
                    ))}

                    {(timedEvents[parseDate(date)] ?? []).map((calendarEvent) => (
                      <EventGridPill
                        key={`${calendarEvent.id}-${calendarEvent.date}`}
                        event={calendarEvent}
                        date={date}
                        narrow={isNarrow}
                        inset={barInset}
                      />
                    ))}

                    <EventTimeMarker date={date} />
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}
